            new_prefix.append(remaining[i])
            new_remaining = list(remaining)
            del new_remaining[i]
            self.selectPermutations(new_prefix, new_remaining, m, result)

    @staticmethod
    def factorial(n):
        result = 1
        for i in range(2, n + 1):
            result *= i
        return result
