```cpp
#include <any>
#include <chrono>
#include <ctime>
#include <iomanip>
#include <map>
#include <memory>
#include <sstream>
#include <string>
#include <vector>

namespace org::example {

using Email = std::map<std::string, std::any>;          // Map<String, Object>
using EmailPtr = std::shared_ptr<Email>;                 // reference to an email
using Inbox = std::vector<EmailPtr>;                     // List<Map<String, Object>>
using InboxPtr = std::shared_ptr<Inbox>;                 // reference to the inbox list

class EmailClient {
private:
    std::string addr;
    double capacity;
    InboxPtr inbox;

    static std::string nowTimestamp() {
        std::time_t now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        std::tm tmBuf{};
        std::tm* local = std::localtime(&now);
        if (local != nullptr) {
            tmBuf = *local;
        }
        std::ostringstream oss;
        oss << std::put_time(&tmBuf, "%Y-%m-%d %H:%M:%S");
        return oss.str();
    }

    static bool tryGetSize(const Email& email, double& out) {
        auto it = email.find("size");
        if (it != email.end() && it->second.has_value() && it->second.type() == typeid(double)) {
            out = std::any_cast<double>(it->second);
            return true;
        }
        return false;
    }

public:
    EmailClient(const std::string& addr, double capacity)
        : addr(addr), capacity(capacity), inbox(std::make_shared<Inbox>()) {}

    bool sendTo(EmailClient& recv, const std::string& content, double size) {
        if (!recv.isFullWithOneMoreEmail(size)) {
            std::string timestamp = nowTimestamp();
            Email email;
            email.emplace("sender", std::any(this->addr));
            email.emplace("receiver", std::any(recv.addr));
            email.emplace("content", std::any(content));
            email.emplace("size", std::any(size));
            email.emplace("time", std::any(timestamp));
            email.emplace("state", std::any(std::string("unread")));
            recv.inbox->push_back(std::make_shared<Email>(std::move(email)));
            return true;
        } else {
            this->clearInbox(size);
            if (recv.isFullWithOneMoreEmail(size)) {
                return false;
            }
            return sendTo(recv, content, size); // Retry sending after clearing
        }
    }

    EmailPtr fetch() {
        if (this->inbox->empty()) {
            return nullptr;
        }
        for (EmailPtr& email : *this->inbox) {
            auto it = email->find("state");
            if (it != email->end() && it->second.has_value()
                && it->second.type() == typeid(std::string)
                && std::any_cast<const std::string&>(it->second) == "unread") {
                (*email)["state"] = std::any(std::string("read"));
                return email;
            }
        }
        return nullptr;
    }

    bool isFullWithOneMoreEmail(double size) const {
        double occupiedSize = this->getOccupiedSize();
        return occupiedSize + size > this->capacity;
    }

    double getOccupiedSize() const {
        double occupiedSize = 0;
        double sz = 0;
        for (const EmailPtr& email : *this->inbox) {
            if (tryGetSize(*email, sz)) {
                occupiedSize += sz;
            }
        }
        return occupiedSize;
    }

    void clearInbox(double size) {
        if (this->addr.empty()) {
            return;
        }
        double freedSpace = 0;
        double sz = 0;
        while (freedSpace < size && !this->inbox->empty()) {
            EmailPtr email = this->inbox->front();
            this->inbox->erase(this->inbox->begin());
            if (tryGetSize(*email, sz)) {
                freedSpace += sz;
            }
        }
    }

    InboxPtr getInbox() const {
        return this->inbox;
    }

    void setInbox(InboxPtr inbox) {
        this->inbox = std::move(inbox);
    }
};

} // namespace org::example
