#include <fstream>
#include <iterator>
#include <regex>
#include <stdexcept>
#include <string>

#include <nlohmann/json.hpp>

class TextFileProcessor {
public:
    explicit TextFileProcessor(std::string file_path)
        : file_path_(std::move(file_path)) {}

    // Analog of Jackson's readValue(..., Object.class): parses any JSON value.
    nlohmann::json read_file_as_json() const {
        std::ifstream file(file_path_, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Failed to open file for reading: " + file_path_);
        }
        return nlohmann::json::parse(file);
    }

    std::string read_file() const {
        std::ifstream file(file_path_, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Failed to open file for reading: " + file_path_);
        }
        return std::string(std::istreambuf_iterator<char>(file),
                           std::istreambuf_iterator<char>());
    }

    void write_file(const std::string& content) const {
        std::ofstream file(file_path_, std::ios::binary | std::ios::trunc);
        if (!file) {
            throw std::runtime_error("Failed to open file for writing: " + file_path_);
        }
        file.write(content.data(), static_cast<std::streamsize>(content.size()));
        if (!file) {
            throw std::runtime_error("Failed to write to file: " + file_path_);
        }
    }

    std::string process_file() const {
        const std::string content = read_file();
        static const std::regex non_alpha("[^a-zA-Z]");
        const std::string processed_content =
            std::regex_replace(content, non_alpha, "");
        write_file(processed_content);
        return processed_content;
    }

private:
    std::string file_path_;
};
```

