class Hotel {
public:
    // available_rooms = {room_type1: room_number1, room_type2: room_number2, ...}
    // e.g. {'single': 5, 'double': 3}
    std::string name;
    std::map<std::string, int> available_rooms;
    // booked_rooms = {room_type1: {name1: room_number1, name2: room_number2, ...}, ...}
    // e.g. {'single': {'name1': 2, 'name2': 1}, 'double': {}}
    std::map<std::string, std::map<std::string, int>> booked_rooms;

    Hotel(std::string hotel_name, std::map<std::string, int> rooms)
        : name(std::move(hotel_name)), available_rooms(std::move(rooms)) {}

    // Returns:
    //  - std::string("Success!") if room_number does not exceed remaining rooms
    //  - int (remaining quantity of this room type) if it exceeds but quantity != 0
    //  - false if it exceeds and quantity is 0, or room_type is unknown
    std::variant<std::string, int, bool> book_room(const std::string& room_type,
                                                   int room_number,
                                                   const std::string& guest_name) {
        // Check if there are any rooms of the specified type available
        auto avail_it = available_rooms.find(room_type);
        if (avail_it == available_rooms.end()) {
            return false;
        }

        if (room_number <= avail_it->second) {
            // Book the room by recording it in the booked_rooms map
            booked_rooms[room_type][guest_name] = room_number;
            avail_it->second -= room_number;
            return std::string("Success!");
        } else if (avail_it->second != 0) {
            return avail_it->second;
        } else {
            return false;
        }
    }

    // Returns:
    //  - false if room_type is not in booked_rooms or room_number exceeds the booked quantity
    //  - std::nullopt otherwise (Python returns None)
    std::optional<bool> check_in(const std::string& room_type,
                                 int room_number,
                                 const std::string& guest_name) {
        auto type_it = booked_rooms.find(room_type);
        if (type_it == booked_rooms.end()) {
            return false;
        }
        auto& guests = type_it->second;
        auto guest_it = guests.find(guest_name);
        if (guest_it != guests.end()) {
            if (room_number > guest_it->second) {
                return false;
            } else if (room_number == guest_it->second) {
                // Check in all booked rooms: remove the guest's booking
                guests.erase(guest_it);
            } else {
                // Partial check-in: booked quantity minus actual quantity remains
                guest_it->second -= room_number;
            }
        }
        return std::nullopt;
    }

    void check_out(const std::string& room_type, int room_number) {
        auto it = available_rooms.find(room_type);
        if (it != available_rooms.end()) {
            it->second += room_number;
        } else {
            available_rooms.emplace(room_type, room_number);
        }
    }

    // Throws std::out_of_range for an unknown room_type (like Python's KeyError)
    int get_available_rooms(const std::string& room_type) const {
        return available_rooms.at(room_type);
    }
};
