    void add_movie(const std::string& name, double price,
                   const std::string& start_time, const std::string& end_time, int n) {
        // datetime.strptime(...) raises ValueError on bad input before anything
        // is appended; do the parsing first to preserve that behavior.
        const int startMinutes = parseTimeToMinutes(start_time);
        const int endMinutes = parseTimeToMinutes(end_time);

        if (n < 0) {
            // numpy raises ValueError("negative dimensions are not allowed")
            throw std::invalid_argument("negative dimensions are not allowed");
        }

        Movie movie;
        movie.name = name;
        movie.price = price;
        movie.startTime = startMinutes;
        movie.endTime = endMinutes;
        movie.seats.assign(static_cast<std::size_t>(n),
                           std::vector<double>(static_cast<std::size_t>(n), 0.0));
        movies.push_back(std::move(movie));
    }

    std::string book_ticket(const std::string& name,
                            const std::vector<std::pair<int, int>>& seats_to_book) {
        for (Movie& movie : movies) {
            if (movie.name == name) {
                for (const std::pair<int, int>& seat : seats_to_book) {
                    const int rows = static_cast<int>(movie.seats.size());
                    const std::size_t row = normalizeIndex(seat.first, rows);
                    std::vector<double>& rowSeats = movie.seats[row];
                    const std::size_t col =
                        normalizeIndex(seat.second, static_cast<int>(rowSeats.size()));
                    if (rowSeats[col] == 0.0) {
                        rowSeats[col] = 1.0;  // partial bookings persist on later failure
                    } else {
                        return "Booking failed.";
                    }
                }
                return "Booking success.";
            }
        }
        return "Movie not found.";
    }

    std::vector<std::string> available_movies(const std::string& start_time,
                                              const std::string& end_time) {
        const int startMinutes = parseTimeToMinutes(start_time);
        const int endMinutes = parseTimeToMinutes(end_time);

        std::vector<std::string> available;
        for (const Movie& movie : movies) {
            if (startMinutes <= movie.startTime && movie.endTime <= endMinutes) {
                available.push_back(movie.name);
            }
        }
        return available;
    }

private:
    // Equivalent of datetime.strptime(s, "%H:%M") restricted to the time part.
    // Accepts 1-2 digit hour (<= 23) and 1-2 digit minute (<= 59), matching
    // Python's strptime; throws std::invalid_argument where Python raises ValueError.
    static int parseTimeToMinutes(const std::string& timeStr) {
        const std::string mismatch =
            "time data '" + timeStr + "' does not match format '%H:%M'";

        std::size_t i = 0;
        auto readField = [&](int maxDigits, int maxValue) -> int {
            int value = 0;
            int digits = 0;
            while (i < timeStr.size() && digits < maxDigits &&
                   std::isdigit(static_cast<unsigned char>(timeStr[i]))) {
                value = value * 10 + (timeStr[i] - '0');
                ++i;
                ++digits;
            }
            if (digits == 0 || (digits == maxDigits && value > maxValue)) {
                throw std::invalid_argument(mismatch);
            }
            return value;
        };

        const int hour = readField(2, 23);
        if (i >= timeStr.size() || timeStr[i] != ':') {
            throw std::invalid_argument(mismatch);
        }
        ++i;
        const int minute = readField(2, 59);
        if (i != timeStr.size()) {
            throw std::invalid_argument("unconverted data remains: '" +
                                        timeStr.substr(i) + "'");
        }
        return hour * 60 + minute;
    }

    // Python/numpy indexing semantics: negative indices count from the end,
    // out-of-range indices raise (Python raises IndexError).
    static std::size_t normalizeIndex(int index, int size) {
        int i = index;
        if (i < 0) i += size;
        if (i < 0 || i >= size) {
            throw std::out_of_range("index " + std::to_string(index) +
                                    " is out of bounds for axis 0 with size " +
                                    std::to_string(size));
        }
        return static_cast<std::size_t>(i);
    }
};
