            "time data '" + time_str + "' does not match format '%H:%M'";

        std::size_t i = 0;
        auto read_field = [&](int max_digits, int max_value) -> int {
            int value = 0;
            int digits = 0;
            while (i < time_str.size() && digits < max_digits &&
