        std::vector<std::size_t> counts;

        for (const double& value : data) {
            std::size_t idx = values.size();
            for (std::size_t k = 0; k < values.size(); ++k) {
                if (values[k] == value) {
                    idx = k;
                    break;
                }
            }
            if (idx == values.size()) {
                values.push_back(value);
                counts.push_back(1);
            } else {
