```cpp
#include <string>
#include <vector>
#include <cctype>

class SplitSentence {
public:
    std::vector<std::string> split_sentences(const std::string& sentences_string) const {
        // regex: (?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s
        std::vector<std::string> result;
        const std::string& s = sentences_string;
        size_t n = s.size();
        size_t start = 0;
        for (size_t i = 0; i < n; ++i) {
            if (!is_space(s[i])) continue;
            // positive lookbehind (?<=\.|\?)
            if (i < 1) continue;
            char prev = s[i-1];
            if (prev != '.' && prev != '?') continue;
            // negative lookbehind (?<!\w\.\w.) : width 4
            if (i >= 4) {
                if (is_word(s[i-4]) && s[i-3] == '.' && is_word(s[i-2]) && s[i-1] != '\n') continue;
            }
            // negative lookbehind (?<![A-Z][a-z]\.) : width 3
            if (i >= 3) {
                if (is_upper(s[i-3]) && is_lower(s[i-2]) && s[i-1] == '.') continue;
            }
            // split at i
            result.push_back(s.substr(start, i - start));
            start = i + 1;
        }
        result.push_back(s.substr(start));
        return result;
    }

    int count_words(const std::string& sentence) const {
        int count = 0;
        bool in_word = false;
        for (char c : sentence) {
            if (is_alpha(c)) {
                if (!in_word) { count++; in_word = true; }
            } else if (is_space(c)) {
                in_word = false;
            }
            // else: char removed, state unchanged
        }
        return count;
    }

    int process_text_file(const std::string& sentences_string) const {
        std::vector<std::string> sentences = split_sentences(sentences_string);
        int max_count = 0;
        for (const auto& sentence : sentences) {
            int count = count_words(sentence);
            if (count > max_count) max_count = count;
        }
        return max_count;
    }

private:
    static bool is_space(char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
    }
    static bool is_word(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_';
    }
    static bool is_upper(char c) { return c >= 'A' && c <= 'Z'; }
    static bool is_lower(char c) { return c >= 'a' && c <= 'z'; }
    static bool is_alpha(char c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'); }
};
```

