#include <string>
#include <vector>

class SplitSentence {
public:
    // Split a string into a list of sentences. Sentences end with . or ? followed by
    // whitespace. Abbreviations such as "Mr." or "e.g." do not end a sentence.
    // Equivalent to Python: re.split(r'(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s', s)
    std::vector<std::string> split_sentences(const std::string& sentences_string) const {
        const std::string& s = sentences_string;
        const std::size_t n = s.size();
        std::vector<std::string> sentences;
        std::size_t start = 0;
        for (std::size_t i = 0; i < n; ++i) {
            if (!is_space(s[i])) continue;              // \s
            if (i == 0) continue;                       // (?<=\.|\?) needs a preceding char
            const char prev = s[i - 1];
            if (prev != '.' && prev != '?') continue;   // (?<=\.|\?)
            // (?<!\w\.\w.)  -- fixed-width (4) lookbehind on s[i-4 .. i-1]
            if (i >= 4 && is_word(s[i - 4]) && s[i - 3] == '.' &&
                is_word(s[i - 2]) && s[i - 1] != '\n') {
                continue;
            }
            // (?<![A-Z][a-z]\.)  -- fixed-width (3) lookbehind on s[i-3 .. i-1]
            if (i >= 3 && is_upper(s[i - 3]) && is_lower(s[i - 2]) && s[i - 1] == '.') {
                continue;
            }
            sentences.push_back(s.substr(start, i - start));
            start = i + 1;
        }
        sentences.push_back(s.substr(start));
        return sentences;
    }

    // Count the number of words in a sentence. Words are separated by whitespace;
    // punctuation and digits are removed before counting.
    // Equivalent to Python: re.sub(r'[^a-zA-Z\s]', '', s).split() length.
    int count_words(const std::string& sentence) const {
        int count = 0;
        bool in_word = false;
        for (const char c : sentence) {
            if (is_alpha(c)) {
                if (!in_word) {
                    ++count;
                    in_word = true;
                }
            } else if (is_space(c)) {
                in_word = false;
            }
            // other characters are stripped by the substitution: they neither
            // start nor end a word.
        }
        return count;
    }

    // Given a text, return the number of words in the longest sentence.
    int process_text_file(const std::string& sentences_string) const {
        const std::vector<std::string> sentences = split_sentences(sentences_string);
        int max_count = 0;
        for (const std::string& sentence : sentences) {
            const int count = count_words(sentence);
            if (count > max_count) {
                max_count = count;
            }
        }
        return max_count;
    }

private:
    // Python's ASCII \s: [ \t\n\r\f\v]
    static bool is_space(const char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
    }
    // Python's ASCII \w: [A-Za-z0-9_]
    static bool is_word(const char c) {
        return is_alpha(c) || is_digit(c) || c == '_';
    }
    static bool is_upper(const char c) { return c >= 'A' && c <= 'Z'; }
    static bool is_lower(const char c) { return c >= 'a' && c <= 'z'; }
    static bool is_alpha(const char c) { return is_upper(c) || is_lower(c); }
    static bool is_digit(const char c) { return c >= '0' && c <= '9'; }
};
