        if isinstance(x, int):
            return self._format_string(str(x))
        if isinstance(x, float):
            return self._format_string('%g' % x)
        return self._format_string(x)

    def _format_string(self, x):
        pos = x.find('.')
        lstr = x[:pos] if pos != -1 else x
        rstr = x[pos + 1:] if pos != -1 else ''
        lstr = lstr[::-1]

        if len(lstr) % 3 == 1:
