    def _norm(vec: Sequence[float]) -> float:
        total = 0.0
        for val in vec:
            total += val * val
        return math.sqrt(total)

    @staticmethod
    def _normalize(vec: Sequence[float]) -> List[float]:
        vec_norm = VectorUtil._norm(vec)
        if vec_norm == 0.0:
            return [0.0] * len(vec)
        return [val / vec_norm for val in vec]

    @staticmethod
