import re


class IPAddress:
    # Emulates Java's Integer.parseInt grammar: an optional sign followed by
    # one or more digits (no whitespace, no underscores, no separators).
    _INT_PATTERN = re.compile(r"[+-]?\d+\Z")

    def __init__(self, ip_address):
        self._ip_address = ip_address

    def _split_octets(self):
        # Java's String.split("\\.") drops trailing empty strings and returns
        # the whole input (as a single element) when no separator is present.
        if "." not in self._ip_address:
            return [self._ip_address]
        parts = self._ip_address.split(".")
        while parts and parts[-1] == "":
            parts.pop()
        return parts

    @staticmethod
    def _parse_int(octet):
        # Mirrors Integer.parseInt, which rejects surrounding whitespace and
        # underscore separators that Python's int() would otherwise accept.
        if not IPAddress._INT_PATTERN.match(octet):
            raise ValueError("For input string: \"%s\"" % octet)
        return int(octet)

    def is_valid(self):
        octets = self._split_octets()
        if len(octets) != 4:
            return False
        for octet in octets:
            try:
                num = self._parse_int(octet)
                if num < 0 or num > 255:
                    return False
            except ValueError:
                return False
        return True

    def get_octets(self):
        octets_list = []
        if self.is_valid():
            for octet in self._split_octets():
                octets_list.append(octet)
        return octets_list

