import re


class IPAddress:
    """Mirrors the Java IPAddress class (org.example.IPAddress)."""

    # Grammar accepted by Java's Integer.parseInt: an optional ASCII sign
    # followed by one or more (Unicode) decimal digits.  Notably this rejects
    # surrounding whitespace and underscore separators, which Python's
    # built-in int() would otherwise tolerate.
    _INT_RE = re.compile(r"[+-]?\d+")

    def __init__(self, ip_address):
        self._ip_address = ip_address

    def _split_octets(self):
        # Emulate Java's String.split("\\."):
        #  * trailing empty strings are discarded,
        #  * a string without any separator yields a single-element list.
        if "." not in self._ip_address:
            return [self._ip_address]
        parts = self._ip_address.split(".")
        while parts and parts[-1] == "":
            parts.pop()
        return parts

    @classmethod
    def _parse_int(cls, value):
        # Behaves like Integer.parseInt: raises ValueError (the analogue of
        # NumberFormatException) for anything outside its grammar.
        if cls._INT_RE.fullmatch(value) is None:
            raise ValueError('For input string: "%s"' % value)
        return int(value)

    def is_valid(self):
        octets = self._split_octets()
        if len(octets) != 4:
            return False
        for octet in octets:
            try:
                num = self._parse_int(octet)
                if num < 0 or num > 255:
                    return False
            except ValueError:
                return False
        return True

    def get_octets(self):
        octets_list = []
        if self.is_valid():
            for octet in self._split_octets():
                octets_list.append(octet)
        return octets_list

    def get_binary(self):
        if self.is_valid():
            binary_parts = []
            for octet in self._split_octets():
                num = self._parse_int(octet)
                binary_parts.append(format(num, "08b"))
            return ".".join(binary_parts)
        return ""
