import re

class NumberConverter:
    _PATTERN_TEMPLATE = r'[+-]?[{}]+'
    _RADIX_DIGITS = {2: '01', 8: '01234567', 16: '0123456789abcdefABCDEF'}
    _MIN_INT = -2 ** 31
    _MAX_INT = 2 ** 31 - 1

