    def _parseInt(s, radix):
        if s is None:
            raise ValueError('null')
        pattern = re.compile('[+-]?[' + NumberConverter._RADIX_DIGITS[radix] + ']+')
        if pattern.fullmatch(s) is None:
            raise ValueError('For input string: "%s"' % s)
        value = int(s, radix)
