```python
import re


class NumberConverter:
    """Python translation of org.example.NumberConverter."""

    _MIN_INT = -(2 ** 31)
    _MAX_INT = 2 ** 31 - 1
    _UINT32_MASK = 0xFFFFFFFF

    # Digit characters accepted by Integer.parseInt for each radix used here.
    _RADIX_DIGITS = {
        2: '01',
        8: '01234567',
        16: '0123456789abcdefABCDEF',
    }

    @staticmethod
    def decimalToBinary(decimal_num):
        # Integer.toBinaryString: unsigned 32-bit view, no leading zeros
        # (negative values appear as 32-bit two's complement).
        return format(decimal_num & NumberConverter._UINT32_MASK, 'b')

    @staticmethod
    def binaryToDecimal(binary_num):
        return NumberConverter._parseInt(binary_num, 2)

    @staticmethod
    def decimalToOctal(decimal_num):
        return format(decimal_num & NumberConverter._UINT32_MASK, 'o')

    @staticmethod
    def octalToDecimal(octal_num):
        return NumberConverter._parseInt(octal_num, 8)

    @staticmethod
    def decimalToHex(decimal_num):
        return format(decimal_num & NumberConverter._UINT32_MASK, 'x')

    @staticmethod
    def hexToDecimal(hex_num):
        return NumberConverter._parseInt(hex_num, 16)

    @staticmethod
    def _parseInt(s, radix):
        """Mirror of Integer.parseInt(String, int) for radix in {2, 8, 16}."""
        if s is None:
            # Java: throw new NumberFormatException("null")
            raise ValueError('null')
        digits = NumberConverter._RADIX_DIGITS[radix]
        # Java accepts an optional single leading '+'/'-' followed only by
        # digits valid for the radix; it rejects everything else (whitespace,
        # "0b"/"0x" prefixes, underscores, empty strings, lone signs, ...).
        if re.fullmatch('[+-]?[' + digits + ']+', s) is None:
            raise ValueError('For input string: "%s"' % s)
        value = int(s, radix)
        # Java throws NumberFormatException when the value does not fit in an int.
        if value < NumberConverter._MIN_INT or value > NumberConverter._MAX_INT:
            raise ValueError('For input string: "%s"' % s)
        return value

    # Idiomatic snake_case aliases for the original Java method names.
    decimal_to_binary = decimalToBinary
    binary_to_decimal = binaryToDecimal
    decimal_to_octal = decimalToOctal
    octal_to_decimal = octalToDecimal
    decimal_to_hex = decimalToHex
    hex_to_decimal = hexToDecimal
```

