def _expand(self, m, replacement, group_count):
    result = []
    i = 0
    n = len(replacement)
    while i < n:
        ch = replacement[i]
        if ch == '\\':
            i += 1
            if i == n:
                raise ValueError("dangling \\ in replacement")
            result.append(replacement[i])
            i += 1
        elif ch == '$':
            i += 1
            if i == n:
                raise ValueError("illegal group reference")
            ch = replacement[i]
            if not ch.isdigit() or not ch.isascii():  # careful: Character.digit? Actually Java uses (int)nextChar - '0' so only ASCII '0'-'9'
                raise ValueError("illegal group reference")
            ref = ord(ch) - ord('0')
            i += 1
            done = False
            while not done:
                if i >= n:
                    break
                nd = replacement[i]
                if nd < '0' or nd > '9':
                    break
                new_ref = ref * 10 + (ord(nd) - ord('0'))
                if group_count < new_ref:
                    done = True
                else:
                    ref = new_ref
                    i += 1
            # group lookup
            if ref > group_count:
                raise IndexError("No group %d" % ref)
            g = m.group(ref)
            if g is not None:
                result.append(g)
        else:
            result.append(ch)
            i += 1
    return ''.join(result)
```

