```python
import math
import random


def _double_div(a, b):
    """IEEE 754 double division, mirroring Java's double '/' semantics
    (division by zero yields +/-inf or nan instead of raising)."""
    if b == 0.0:
        if a == 0.0 or a != a:  # 0/0 or NaN/x -> NaN
            return float("nan")
        sign = math.copysign(1.0, a) * math.copysign(1.0, b)
        return math.copysign(math.inf, sign)
    return a / b


class TwentyFourPointGame:
    def __init__(self):
        self.nums = self._get_my_cards()

    def _get_my_cards(self):
        return [random.randint(1, 9) for _ in range(4)]

    def answer(self, expression):
        if expression == "pass":
            self.nums = self._get_my_cards()
            return False

        counts = [0] * 10
        for c in expression:
            if c.isdecimal():
                counts[int(c)] += 1

        for num in self.nums:
            if counts[num] > 0:
                counts[num] -= 1
            else:
                return False

        for count in counts:
            if count != 0:
                return False

        return self.evaluate_expression(expression)

    def evaluate_expression(self, expression):
        try:
            pos = -1
            ch = -1

            def next_char():
                nonlocal pos, ch
                pos += 1
                ch = ord(expression[pos]) if pos < len(expression) else -1

            def eat(char_to_eat):
                while ch == 32:  # ' '
                    next_char()
                if ch == char_to_eat:
                    next_char()
                    return True
                return False

            def parse():
                next_char()
                x = parse_expression()
                if pos < len(expression):
                    raise ValueError("Unexpected: " + (chr(ch) if ch >= 0 else ""))
                return x

            def parse_expression():
                x = parse_term()
                while True:
                    if eat(43):  # '+'
                        x += parse_term()
                    elif eat(45):  # '-'
                        x -= parse_term()
                    else:
                        return x

            def parse_term():
                x = parse_factor()
                while True:
                    if eat(42):  # '*'
                        x *= parse_factor()
                    elif eat(47):  # '/'
                        x = _double_div(x, parse_factor())
                    else:
                        return x

            def parse_factor():
                if eat(43):  # '+'
                    return parse_factor()
                if eat(45):  # '-'
                    return -parse_factor()

                start_pos = pos
                if eat(40):  # '('
                    x = parse_expression()
                    eat(41)  # ')'
                elif (48 <= ch <= 57) or ch == 46:  # '0'-'9' or '.'
                    while (48 <= ch <= 57) or ch == 46:
                        next_char()
                    x = float(expression[start_pos:pos])
                else:
                    raise ValueError("Unexpected: " + (chr(ch) if ch >= 0 else ""))
                return x

            return parse() == 24
        except Exception:
            return False

    def get_nums(self):
        return self.nums
```

