namespace org {
namespace example {

class DataStatistics4 {
private:
    // Equivalent of Java's stream().mapToDouble(...).sum()
    template <typename UnaryOp>
    static double sum(const std::vector<double>& data, UnaryOp op) {
        double sum = 0.0;
        for (double x : data) {
            sum += op(x);
        }
        return sum;
    }

