    template <typename UnaryOp>
    static double averageOrZero(const std::vector<double>& data, UnaryOp op) {
        if (data.empty()) {
            return 0.0;
        }
        return sum(data, op) / static_cast<double>(data.size());
    }

public:
    static double correlationCoefficient(const std::vector<double>& data1, const std::vector<double>& data2) {
        int n = static_cast<int>(data1.size());
        double mean1 = averageOrZero(data1, [](double x) { return x; });
        double mean2 = averageOrZero(data2, [](double x) { return x; });

        double numerator = 0.0;
        for (int i = 0; i < n; ++i) {
            numerator += (data1[i] - mean1) * (data2.at(i) - mean2);
        }

        double denominator = std::sqrt(sum(data1, [&](double x) { return (x - mean1) * (x - mean1); }))
                           * std::sqrt(sum(data2, [&](double x) { return (x - mean2) * (x - mean2); }));

        return denominator != 0 ? numerator / denominator : 0;
    }

    static double skewness(const std::vector<double>& data) {
        int n = static_cast<int>(data.size());
        double mean = averageOrZero(data, [](double x) { return x; });
        double variance = averageOrZero(data, [&](double x) { return (x - mean) * (x - mean); });
        double stdDeviation = std::sqrt(variance);

        if (stdDeviation == 0) {
            return 0;
        }

        double skewnessValue = sum(data, [&](double x) { return (x - mean) * (x - mean) * (x - mean); })
                             * n / ((n - 1) * (n - 2) * std::pow(stdDeviation, 3));

        return skewnessValue;
    }

    static double kurtosis(const std::vector<double>& data) {
        int n = static_cast<int>(data.size());
        (void)n; // Unused in the original Java code as well
        double mean = averageOrZero(data, [](double x) { return x; });
        double stdDev = std::sqrt(averageOrZero(data, [&](double x) { return (x - mean) * (x - mean); }));

        if (stdDev == 0) {
            return std::numeric_limits<double>::quiet_NaN();
        }

        std::vector<double> centeredData;
        centeredData.reserve(data.size());
        for (double x : data) {
            centeredData.push_back(x - mean);
        }

        double fourthMoment = averageOrZero(centeredData, [](double x) { return std::pow(x, 4); });

        double kurtosisValue = (fourthMoment / std::pow(stdDev, 4)) - 3;

        return kurtosisValue;
    }

    static std::vector<double> pdf(const std::vector<double>& data, double mu, double sigma) {
        static constexpr double PI = 3.14159265358979323846;

        std::vector<double> result;
        result.reserve(data.size());
        for (double x : data) {
            result.push_back((1 / (sigma * std::sqrt(2 * PI))) * std::exp(-0.5 * std::pow((x - mu) / sigma, 2)));
        }
        return result;
    }
};

