#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

namespace org {
namespace example {

class BigNumCalculator {
public:
    static std::string add(const std::string& num1, const std::string& num2) {
        int maxLength = static_cast<int>(std::max(num1.length(), num2.length()));
        std::string a = padLeft(num1, maxLength);
        std::string b = padLeft(num2, maxLength);

        int carry = 0;
        std::string result;
        for (int i = maxLength - 1; i >= 0; i--) {
            int digitSum = getNumericValue(a[i]) + getNumericValue(b[i]) + carry;
            carry = digitSum / 10;
            int digit = digitSum % 10;
            result = std::to_string(digit) + result;
        }

        if (carry > 0) {
            result = std::to_string(carry) + result;
        }

        return result;
    }

    static std::string subtract(const std::string& num1, const std::string& num2) {
        std::string a = num1;
        std::string b = num2;
        bool negative = false;
        if (a.length() < b.length() || (a.length() == b.length() && a < b)) {
            std::string temp = a;
            a = b;
            b = temp;
            negative = true;
        }

        int maxLength = static_cast<int>(std::max(a.length(), b.length()));
        a = padLeft(a, maxLength);
        b = padLeft(b, maxLength);

        int borrow = 0;
        std::string result;
        for (int i = maxLength - 1; i >= 0; i--) {
            int digitDiff = getNumericValue(a[i]) - getNumericValue(b[i]) - borrow;

            if (digitDiff < 0) {
                digitDiff += 10;
                borrow = 1;
            } else {
                borrow = 0;
            }

            result = std::to_string(digitDiff) + result;
        }

        while (result.length() > 1 && result[0] == '0') {
            result.erase(0, 1);
        }

        if (negative) {
            result.insert(0, 1, '-');
        }

        return result;
    }

    static std::string multiply(const std::string& num1, const std::string& num2) {
        int len1 = static_cast<int>(num1.length());
        int len2 = static_cast<int>(num2.length());
        std::vector<int> result(static_cast<std::size_t>(len1 + len2), 0);

        for (int i = len1 - 1; i >= 0; i--) {
            for (int j = len2 - 1; j >= 0; j--) {
                int mul = getNumericValue(num1[i]) * getNumericValue(num2[j]);
                int p1 = i + j;
                int p2 = i + j + 1;
                int total = mul + result[p2];

                result[p1] += total / 10;
                result[p2] = total % 10;
            }
        }

        std::string sb;
        int start = 0;
        while (start < static_cast<int>(result.size()) - 1 && result[start] == 0) {
            start++;
        }

        for (std::size_t i = start; i < result.size(); i++) {
            sb += std::to_string(result[i]);
        }

        return sb;
    }

private:
    static std::string padLeft(const std::string& s, int width) {
        std::string out;
        if (static_cast<int>(s.length()) < width) {
            out.append(static_cast<std::size_t>(width) - s.length(), ' ');
        }
        out += s;
        for (std::size_t k = 0; k < out.length(); k++) {
            if (out[k] == ' ') {
                out[k] = '0';
            }
        }
        return out;
    }

    static int getNumericValue(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'z') return c - 'a' + 10;
        if (c >= 'A' && c <= 'Z') return c - 'A' + 10;
        return -1;
    }
};

} // namespace example
} // namespace org

int main() {
    std::cout << org::example::BigNumCalculator::add("12345678901234567890", "98765432109876543210") << "\n";
    std::cout << org::example::BigNumCalculator::subtract("12345678901234567890", "98765432109876543210") << "\n";
    std::cout << org::example::BigNumCalculator::multiply("12345678901234567890", "98765432109876543210") << "\n";
    return 0;
}
