        skipWhitespace();
        JsonValue value = parseValue();
        v.object.emplace_back(std::move(key), std::move(value));
        skipWhitespace();
        char c = peek();
        if (c == ',') { ++pos_; continue; }
        if (c == '}') { ++pos_; break; }
        throw ParseException("Expected ',' or '}'");
