// Returns code point and advances i; returns -1 on invalid.
static int decodeUtf8(const std::string& s, std::size_t& i) {
    unsigned char c = s[i];
    if (c < 0x80) { ++i; return c; }
    if ((c & 0xE0) == 0xC0) {
        if (i + 1 >= s.size() || (s[i+1] & 0xC0) != 0x80) return -1;
        int cp = ((c & 0x1F) << 6) | (s[i+1] & 0x3F);
        i += 2;
        return cp;
    }
    if ((c & 0xF0) == 0xE0) {
        if (i + 2 >= s.size() || (s[i+1] & 0xC0) != 0x80 || (s[i+2] & 0xC0) != 0x80) return -1;
        int cp = ((c & 0x0F) << 12) | ((s[i+1] & 0x3F) << 6) | (s[i+2] & 0x3F);
        i += 3;
        return cp;
    }
    if ((c & 0xF8) == 0xF0) {
        if (i + 3 >= s.size() || (s[i+1] & 0xC0) != 0x80 || (s[i+2] & 0xC0) != 0x80 || (s[i+3] & 0xC0) != 0x80) return -1;
