static void appendEscaped(std::string& out, const std::string& s) {
    std::size_t i = 0;
    while (i < s.size()) {
        std::size_t start = i;
        int cp = decodeUtf8(s, i);
        if (cp < 0) {
            // Invalid UTF-8 byte: write it raw (Java would produce U+FFFD; keep bytes to avoid data loss).
            out += s[start];
            i = start + 1;
            continue;
        }
        if (cp == '"') { out += "\\\""; }
        else if (cp == '\\') { out += "\\\\"; }
        else if (cp == '\b') { out += "\\b"; }
        else if (cp == '\f') { out += "\\f"; }
        else if (cp == '\n') { out += "\\n"; }
        else if (cp == '\r') { out += "\\r"; }
        else if (cp == '\t') { out += "\\t"; }
        else if ((cp >= 0x0000 && cp <= 0x001F) || (cp >= 0x007F && cp <= 0x009F) || (cp >= 0x2000 && cp <= 0x20FF)) {
            char buf[8];
            std::snprintf(buf, sizeof(buf), "\\u%04X", cp);
            out += buf;
        } else {
            out.append(s, start, i - start);  // raw UTF-8 bytes
        }
    }
}
