// Analog of java.sql.SQLException being caught and printed via
// e.printStackTrace(): the error message is written to stderr.
void printSqliteError(sqlite3* conn) {
    std::cerr << "java.sql.SQLException: " << sqlite3_errmsg(conn) << std::endl;
}

// RAII wrapper standing in for the JDBC Connection (try-with-resources).
class Connection {
public:
    explicit Connection(const std::string& path)
        : ok_(sqlite3_open(path.c_str(), &handle_) == SQLITE_OK) {}

    ~Connection() {
        if (handle_) {
            sqlite3_close(handle_);
        }
    }

    Connection(const Connection&) = delete;
    Connection& operator=(const Connection&) = delete;

    bool isOk() const { return ok_; }
    sqlite3* handle() const { return handle_; }

private:
    sqlite3* handle_ = nullptr;
    bool ok_ = false;
};

// RAII wrapper standing in for the JDBC Statement.
class Statement {
public:
    Statement(sqlite3* conn, const std::string& sql) {
        if (sqlite3_prepare_v2(conn, sql.c_str(), -1, &stmt_, nullptr) != SQLITE_OK) {
            std::cerr << "java.sql.SQLException: " << sqlite3_errmsg(conn) << std::endl;
        }
    }

    ~Statement() {
        if (stmt_) {
            sqlite3_finalize(stmt_);
        }
    }

    Statement(const Statement&) = delete;
    Statement& operator=(const Statement&) = delete;

    bool isValid() const { return stmt_ != nullptr; }
    sqlite3_stmt* handle() const { return stmt_; }

private:
    sqlite3_stmt* stmt_ = nullptr;
};

// Equivalent of Java's String.format("%s", obj) for the values stored in the
// maps: null renders as "null", other values via their textual form.
std::string formatObject(const std::any& value) {
    if (!value.has_value()) {
        return "null";
    }
    if (const auto* s = std::any_cast<std::string>(&value)) {
        return *s;
    }
    if (const auto* c = std::any_cast<const char*>(&value)) {
        return *c;
    }
    if (const auto* i = std::any_cast<int>(&value)) {
        return std::to_string(*i);
    }
    if (const auto* l = std::any_cast<long long>(&value)) {
        return std::to_string(*l);
    }
    if (const auto* d = std::any_cast<double>(&value)) {
        return std::to_string(*d);
    }
    if (const auto* b = std::any_cast<bool>(&value)) {
        return *b ? "true" : "false";
    }
    return "<unknown>";
}

} // namespace
