// Analog of `catch (SQLException e) { e.printStackTrace(); }`: the error is
// reported on stderr and execution continues.
void reportSqlError(const std::string& message) {
    std::cerr << "java.sql.SQLException: " << message << std::endl;
}

void reportSqlError(sqlite3* connection) {
    reportSqlError(sqlite3_errmsg(connection));
