// RAII wrapper for sqlite3*, the counterpart of the JDBC Connection that
// try-with-resources closes at the end of each method.
class Connection {
public:
    explicit Connection(const std::string& name)
        : openedOk_(sqlite3_open(name.c_str(), &handle_) == SQLITE_OK) {}

    ~Connection() {
        if (handle_ != nullptr) {
            sqlite3_close(handle_);
        }
    }

    Connection(const Connection&) = delete;
    Connection& operator=(const Connection&) = delete;

    bool openedOk() const { return openedOk_; }
    sqlite3* get() const { return handle_; }

private:
    sqlite3* handle_ = nullptr;
    bool openedOk_ = false;
};

// RAII wrapper for sqlite3_stmt*, the counterpart of the JDBC Statement.
class Statement {
public:
    Statement(sqlite3* connection, const std::string& sql)
        : preparedOk_(sqlite3_prepare_v2(connection, sql.c_str(), -1,
                                         &handle_, nullptr) == SQLITE_OK) {}

    ~Statement() {
        if (handle_ != nullptr) {
            sqlite3_finalize(handle_);
        }
    }

    Statement(const Statement&) = delete;
    Statement& operator=(const Statement&) = delete;

    bool preparedOk() const { return preparedOk_; }
    sqlite3_stmt* get() const { return handle_; }

private:
    sqlite3_stmt* handle_ = nullptr;
    bool preparedOk_ = false;
};

// Equivalent of Java's String.format("%s", obj) for map values: a missing
// value renders as "null", everything else via its textual representation.
std::string formatObject(const std::any& value) {
    if (!value.has_value()) {
        return "null";
    }
    if (const auto* text = std::any_cast<std::string>(&value)) {
        return *text;
    }
    if (const auto* text = std::any_cast<const char*>(&value)) {
        return *text;
    }
    if (const auto* number = std::any_cast<int>(&value)) {
        return std::to_string(*number);
    }
    if (const auto* number = std::any_cast<long long>(&value)) {
        return std::to_string(*number);
    }
    if (const auto* number = std::any_cast<double>(&value)) {
        return std::to_string(*number);
    }
    if (const auto* flag = std::any_cast<bool>(&value)) {
        return *flag ? "true" : "false";
    }
    return value.type().name();
}

// Resolves a column label to its index, like ResultSet.getXxx(String).
int columnIndex(const Statement& statement, const char* label) {
    const int count = sqlite3_column_count(statement.get());
    for (int index = 0; index < count; ++index) {
        const char* name = sqlite3_column_name(statement.get(), index);
        if (name != nullptr && std::strcmp(name, label) == 0) {
            return index;
        }
    }
    return -1;
}

}  // namespace

