LocalTime LocalTime::parse(const std::string& text) {
    const std::string failMsg = "Text '" + text + "' could not be parsed";
    auto isDigit = [](char c) {
        return c >= '0' && c <= '9';
    };

    size_t i = 0;
    auto readFixedTwoDigits = [&](const char* field) -> int {
        if (i + 2 > text.size() || !isDigit(text[i]) || !isDigit(text[i + 1])) {
            throw std::invalid_argument(failMsg + ": expected two digits for " + field);
        }
        int value = (text[i] - '0') * 10 + (text[i + 1] - '0');
        i += 2;
        return value;
    };

    int hour = readFixedTwoDigits("hour");
    if (i >= text.size() || text[i] != ':') {
        throw std::invalid_argument(failMsg + ": expected ':'");
    }
    ++i;
    int minute = readFixedTwoDigits("minute");

    int second = 0;
    int nano = 0;
    if (i < text.size() && text[i] == ':') {
        ++i;
        second = readFixedTwoDigits("second");
        if (i < text.size() && text[i] == '.') {
            ++i;
            size_t fracStart = i;
            while (i < text.size() && isDigit(text[i])) ++i;
            size_t fracCount = i - fracStart;
            if (fracCount == 0) throw std::invalid_argument(failMsg + ": expected fractional digits");
            if (fracCount > 9) throw std::invalid_argument(failMsg + ": invalid fraction");
            int scale = 100000000; // 1e8
            for (size_t k = fracStart; k < i; ++k) {
                nano += (text[k] - '0') * scale;
                scale /= 10;
            }
        }
    }
    if (i != text.size()) {
        throw std::invalid_argument(failMsg + ": unparsed text");
    }
    if (hour > 23) throw std::invalid_argument(failMsg + ": invalid hour");
    if (minute > 59) throw std::invalid_argument(failMsg + ": invalid minute");
    if (second > 59) throw std::invalid_argument(failMsg + ": invalid second");
    return LocalTime(hour, minute, second, nano);
}
```

