LocalTime LocalTime::parse(const std::string& text) {
    const std::string failMessage = "Text '" + text + "' could not be parsed";
    auto fail = [&failMessage]() { throw std::invalid_argument(failMessage); };
    auto isDigit = [](char c) { return c >= '0' && c <= '9'; };

    std::size_t i = 0;
    auto readTwoDigits = [&](const std::string& field) -> int {
        if (i + 2 > text.size() || !isDigit(text[i]) || !isDigit(text[i + 1])) {
            fail();
        }
        int value = (text[i] - '0') * 10 + (text[i + 1] - '0');
        i += 2;
        return value;
    };

    const int hour = readTwoDigits("hour");
    if (i >= text.size() || text[i] != ':') {
        fail();
    }
    ++i;
    const int minute = readTwoDigits("minute");

    int second = 0;
    int nano = 0;
    if (i < text.size() && text[i] == ':') {
        ++i;
        second = readTwoDigits("second");
        if (i < text.size() && text[i] == '.') {
            ++i;
            const std::size_t fractionStart = i;
            while (i < text.size() && isDigit(text[i])) {
                ++i;
            }
            const std::size_t digitCount = i - fractionStart;
            if (digitCount == 0 || digitCount > 9) {
                fail();
            }
            int scale = 100000000; // 10^8
            for (std::size_t k = fractionStart; k < i; ++k) {
                nano += (text[k] - '0') * scale;
                scale /= 10;
            }
        }
    }

    if (i != text.size()) {
        fail();
    }
    if (hour > 23 || minute > 59 || second > 59) {
        fail();
    }

    return LocalTime(hour, minute, second, nano);
}
