    int minute() const { return minute_; }
    int second() const { return second_; }
    int nano() const { return nano_; }

    friend bool operator==(const LocalTime& lhs, const LocalTime& rhs) { return lhs.compare(rhs) == 0; }
    friend bool operator!=(const LocalTime& lhs, const LocalTime& rhs) { return !(lhs == rhs); }
