std::vector<Event> getUpcomingEvents(int num_events) const {
    if (num_events < 0) {
        // java.util.stream.Stream#limit throws IllegalArgumentException for negative sizes
        throw std::invalid_argument(std::to_string(num_events));
    }
    const LocalDateTime now = LocalDateTime::now();
    std::vector<Event> upcoming;
    const std::size_t limit = static_cast<std::size_t>(num_events);
    for (const Event& event : events) {
        if (upcoming.size() == limit) break;
        if (event.start_time.isAfter(now)) {
            upcoming.push_back(event);
        }
    }
    return upcoming;
