#include <algorithm>
#include <any>
#include <optional>
#include <string>
#include <unordered_map>
#include <vector>

class Server {
private:
    std::vector<int> whiteList;
    std::unordered_map<std::string, std::any> sendStruct;
    std::unordered_map<std::string, std::any> receiveStruct;

public:
    Server() = default;

    // Returns nullptr when addr is already whitelisted;
    // otherwise returns a pointer to the whitelist (like Java returning the list, or null).
    std::vector<int>* addWhiteList(int addr) {
        if (std::find(whiteList.begin(), whiteList.end(), addr) != whiteList.end()) {
            return nullptr;
        }
        whiteList.push_back(addr);
        return &whiteList;
    }

    // Returns nullptr when addr is not in the whitelist;
    // otherwise removes the first occurrence and returns a pointer to the whitelist.
    std::vector<int>* delWhiteList(int addr) {
        auto it = std::find(whiteList.begin(), whiteList.end(), addr);
        if (it == whiteList.end()) {
            return nullptr;
        }
        whiteList.erase(it);
        return &whiteList;
    }

    // Returns std::any holding:
    //   int(-1)          -> when info is null or malformed,
    //   bool(false)      -> when addr is not whitelisted,
    //   std::string      -> the received content.
    // std::any_cast throws std::bad_any_cast analogously to Java's ClassCastException.
    std::any recv(const std::unordered_map<std::string, std::any>* info) {
        if (info == nullptr || info->find("addr") == info->end() ||
            info->find("content") == info->end()) {
            return std::any(-1);
        }
        int addr = std::any_cast<int>(info->at("addr"));
        std::string content = std::any_cast<std::string>(info->at("content"));
        if (std::find(whiteList.begin(), whiteList.end(), addr) == whiteList.end()) {
            return std::any(false);
        }
        receiveStruct["addr"] = addr;
        receiveStruct["content"] = content;
        return receiveStruct["content"];
    }

    // Returns the error message when info is null or malformed;
    // returns std::nullopt on success (Java returns null).
    std::optional<std::string> send(const std::unordered_map<std::string, std::any>* info) {
        if (info == nullptr || info->find("addr") == info->end() ||
            info->find("content") == info->end()) {
            return std::string("info structure is not correct");
        }
        sendStruct["addr"] = info->at("addr");
        sendStruct["content"] = info->at("content");
        return std::nullopt;
    }

    // Returns nullptr for unknown (or null) type, mirroring the null-safe
    // "send".equals(type) / "receive".equals(type) checks.
    std::unordered_map<std::string, std::any>* show(const std::string* type) {
        if (type != nullptr && *type == "send") {
            return &sendStruct;
        } else if (type != nullptr && *type == "receive") {
            return &receiveStruct;
        } else {
            return nullptr;
        }
    }
};
```

