#include <cstddef>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

class EncryptionUtils {
private:
    std::string key;

    // ASCII equivalents of Character.isLetter/isUpperCase/toLowerCase/toUpperCase.
    // Explicit range checks are used (instead of <cctype>) so that behavior
    // never depends on the current C locale.
    static bool isLetter(char c) {
        return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
    }

    static bool isUpperCase(char c) {
        return c >= 'A' && c <= 'Z';
    }

    static char toLowerCase(char c) {
        return (c >= 'A' && c <= 'Z') ? static_cast<char>(c - 'A' + 'a') : c;
    }

    static char toUpperCase(char c) {
        return (c >= 'a' && c <= 'z') ? static_cast<char>(c - 'a' + 'A') : c;
    }

public:
    explicit EncryptionUtils(std::string key) : key(std::move(key)) {}

    std::string caesarCipher(const std::string& plaintext, int shift) const {
        std::string ciphertext;
        for (char c : plaintext) {
            if (isLetter(c)) {
                int asciiOffset = isUpperCase(c) ? 'A' : 'a';
                char shiftedChar = static_cast<char>((c - asciiOffset + shift) % 26 + asciiOffset);
                ciphertext.push_back(shiftedChar);
            }
            else {
                ciphertext.push_back(c);
            }
        }
        return ciphertext;
    }

    std::string vigenereCipher(const std::string& plainText) const {
        std::string encryptedText;
        std::size_t keyIndex = 0;
        for (char c : plainText) {
            if (isLetter(c)) {
                if (key.empty()) {
                    // Java: `keyIndex % key.length()` throws ArithmeticException("/ by zero").
                    throw std::runtime_error("/ by zero");
                }
                int shift = toLowerCase(key[keyIndex % key.length()]) - 'a';
                char encryptedChar = static_cast<char>((toLowerCase(c) - 'a' + shift) % 26 + 'a');
                encryptedText.push_back(isUpperCase(c) ? toUpperCase(encryptedChar) : encryptedChar);
                ++keyIndex;
            }
            else {
                encryptedText.push_back(c);
            }
        }
        return encryptedText;
    }

    std::string railFenceCipher(const std::string& plainText, int rails) const {
        if (rails < 0) {
            // Java: `new char[rails][...]` throws NegativeArraySizeException.
            throw std::length_error("negative array size");
        }

        std::vector<std::vector<char>> fence(
            static_cast<std::size_t>(rails),
            std::vector<char>(plainText.length(), '\n'));

        int direction = -1;
        int row = 0, col = 0;

        for (char c : plainText) {
            if (row == 0 || row == rails - 1) {
                direction = -direction;
            }

            // .at() mirrors Java's array bounds checking
            // (ArrayIndexOutOfBoundsException -> std::out_of_range).
            fence.at(static_cast<std::size_t>(row))
                .at(static_cast<std::size_t>(col)) = c;
            ++col;
            row += direction;
        }

        std::string encryptedText;
        for (int i = 0; i < rails; ++i) {
            for (std::size_t j = 0; j < plainText.length(); ++j) {
                if (fence[static_cast<std::size_t>(i)][j] != '\n') {
                    encryptedText.push_back(fence[static_cast<std::size_t>(i)][j]);
                }
            }
        }
        return encryptedText;
    }
};
