```cpp
#include <optional>
#include <queue>
#include <stdexcept>
#include <string>
#include <unordered_set>
#include <utility>
#include <vector>

class EightPuzzle {
public:
    explicit EightPuzzle(const std::vector<std::vector<int>>& initialState)
        : initialState(deepCopy(initialState)),
          goalState({{1, 2, 3}, {4, 5, 6}, {7, 8, 0}}) {}

    // Java returns int[]{i, j} or null; null maps to std::nullopt.
    std::optional<std::pair<int, int>> findBlank(const std::vector<std::vector<int>>& state) const {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (state.at(i).at(j) == 0) {
                    return std::make_pair(i, j);
                }
            }
        }
        return std::nullopt;
    }

    std::vector<std::vector<int>> move(const std::vector<std::vector<int>>& state,
                                       const std::string& direction) const {
        std::optional<std::pair<int, int>> blank = findBlank(state);
        if (!blank.has_value()) {
            // Java would throw a NullPointerException at blank[0].
            throw std::runtime_error("blank tile not found");
        }
        int i = blank->first;
        int j = blank->second;
        std::vector<std::vector<int>> newState = deepCopy(state);

        if (direction == "up") {
            if (i > 0) {
                newState.at(i).at(j) = newState.at(i - 1).at(j);
                newState.at(i - 1).at(j) = 0;
            }
        } else if (direction == "down") {
            if (i < 2) {
                newState.at(i).at(j) = newState.at(i + 1).at(j);
                newState.at(i + 1).at(j) = 0;
            }
        } else if (direction == "left") {
            if (j > 0) {
                newState.at(i).at(j) = newState.at(i).at(j - 1);
                newState.at(i).at(j - 1) = 0;
            }
        } else if (direction == "right") {
            if (j < 2) {
                newState.at(i).at(j) = newState.at(i).at(j + 1);
                newState.at(i).at(j + 1) = 0;
            }
        }
        return newState;
    }

    std::vector<std::string> getPossibleMoves(const std::vector<std::vector<int>>& state) const {
        std::vector<std::string> moves;
        std::optional<std::pair<int, int>> blank = findBlank(state);
        if (!blank.has_value()) {
            throw std::runtime_error("blank tile not found");
        }
        int i = blank->first;
        int j = blank->second;

        if (i > 0) moves.push_back("up");
        if (i < 2) moves.push_back("down");
        if (j > 0) moves.push_back("left");
        if (j < 2) moves.push_back("right");

        return moves;
    }

    // Java returns the move list, or null when unsolvable; null maps to std::nullopt.
    std::optional<std::vector<std::string>> solve() {
        std::queue<Node> openList;
        std::unordered_set<std::string> closedList;
        openList.push(Node(initialState, std::vector<std::string>()));

        while (!openList.empty()) {
            Node currentNode = std::move(openList.front());
            openList.pop();
            std::vector<std::vector<int>>& currentState = currentNode.state;
            std::vector<std::string>& path = currentNode.path;
            closedList.insert(stateToString(currentState));

            if (currentState == goalState) {
                return path;
            }

            for (const std::string& direction : getPossibleMoves(currentState)) {
                std::vector<std::vector<int>> newState = move(currentState, direction);
                if (closedList.find(stateToString(newState)) == closedList.end()) {
                    std::vector<std::string> newPath = path;
                    newPath.push_back(direction);
                    openList.push(Node(std::move(newState), std::move(newPath)));
                }
            }
        }
        return std::nullopt;
    }

private:
    std::vector<std::vector<int>> initialState;
    std::vector<std::vector<int>> goalState;

    struct Node {
        std::vector<std::vector<int>> state;
        std::vector<std::string> path;

        Node(std::vector<std::vector<int>> state, std::vector<std::string> path)
            : state(std::move(state)), path(std::move(path)) {}
    };

    static std::string stateToString(const std::vector<std::vector<int>>& state) {
        std::string sb;
        for (const std::vector<int>& row : state) {
            for (int val : row) {
                sb += std::to_string(val);
            }
        }
        return sb;
    }

    static std::vector<std::vector<int>> deepCopy(const std::vector<std::vector<int>>& original) {
        std::vector<std::vector<int>> copy(original.size());
        for (std::size_t i = 0; i < original.size(); i++) {
            copy[i] = original[i];
        }
        return copy;
    }
};
```

