#pragma once

#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <functional>
#include <string>
#include <unordered_map>

// Java doubles are always 64-bit IEEE-754; the hashCode()/equals() emulation
// below relies on the same representation here.
static_assert(sizeof(double) == 8, "This translation assumes 64-bit IEEE-754 doubles.");

namespace org {
namespace example {

class ShoppingCart {
public:
    // Equivalent of the Java public static nested class ShoppingCart.Item.
    class Item {
    public:
        Item(double price, int quantity) : price(price), quantity(quantity) {}

        double getPrice() const { return price; }
        void setPrice(double price) { this->price = price; }

        int getQuantity() const { return quantity; }
        void setQuantity(int quantity) { this->quantity = quantity; }

        // Equivalent of the Java equals(Object) override.
        bool operator==(const Item& item) const {
            return doubleCompare(item.price, price) == 0 && quantity == item.quantity;
        }

        bool operator!=(const Item& item) const {
            return !(*this == item);
        }

        // Equivalent of the Java hashCode() override: Objects.hash(price, quantity).
        int hashCode() const {
            unsigned int result = 1u;
            result = 31u * result + static_cast<unsigned int>(doubleHashCode(price));
            result = 31u * result + static_cast<unsigned int>(quantity);
            return static_cast<int>(result);
        }

    private:
        double price;
        int quantity;

        // Mirrors java.lang.Double.compare (NaN == NaN, -0.0 < +0.0).
        static int doubleCompare(double a, double b) {
            if (a < b) return -1;
            if (a > b) return 1;
            const bool nanA = std::isnan(a);
            const bool nanB = std::isnan(b);
            if (nanA && nanB) return 0;
            if (nanA) return 1;
            if (nanB) return -1;
            if (a == 0.0 && b == 0.0 && std::signbit(a) != std::signbit(b)) {
                return std::signbit(a) ? -1 : 1;
            }
            return 0;
        }

        // Mirrors java.lang.Double.hashCode (doubleToLongBits with canonical NaN).
        static int doubleHashCode(double value) {
            std::uint64_t bits;
            if (std::isnan(value)) {
                bits = 0x7FF8000000000000ULL;  // canonical NaN bit pattern
            } else {
                std::memcpy(&bits, &value, sizeof(bits));
            }
            const std::uint32_t low = static_cast<std::uint32_t>(bits);
            const std::uint32_t high = static_cast<std::uint32_t>(bits >> 32);
            return static_cast<int>(low ^ high);
        }
    };

    ShoppingCart() = default;  // items starts empty, like new HashMap<>()

    void addItem(const std::string& item, double price, int quantity) {
        const auto it = items.find(item);
        if (it != items.end()) {
            Item& existingItem = it->second;
            existingItem.setPrice(price);
            existingItem.setQuantity(wrapAdd(existingItem.getQuantity(), quantity));
        } else {
            items.emplace(item, Item(price, quantity));
        }
    }

    void removeItem(const std::string& item, int quantity) {
        const auto it = items.find(item);
        if (it != items.end()) {
            Item& existingItem = it->second;
            const int newQuantity = wrapSub(existingItem.getQuantity(), quantity);
            if (newQuantity <= 0) {
                items.erase(it);
            } else {
                existingItem.setQuantity(newQuantity);
            }
        }
    }

    // Returns a new map with the current contents, like new HashMap<>(items).
    // (Item is a value type in C++, so the copy is deep.)
    std::unordered_map<std::string, Item> viewItems() const {
        return items;
    }

    double totalPrice() const {
        double total = 0.0;
        for (const auto& entry : items) {
            const Item& item = entry.second;
            total += item.getPrice() * item.getQuantity();
        }
        return total;
    }

private:
    std::unordered_map<std::string, Item> items;

    // Java int arithmetic wraps on overflow; reproduce that bit-exactly
    // (signed overflow would be UB in C++).
    static int wrapAdd(int a, int b) {
        return static_cast<int>(static_cast<unsigned int>(a) + static_cast<unsigned int>(b));
    }

    static int wrapSub(int a, int b) {
        return static_cast<int>(static_cast<unsigned int>(a) - static_cast<unsigned int>(b));
    }

