// Translation of org.example.StudentDatabaseProcessor (Java + JDBC/SQLite)
// to C++ using the SQLite3 C API.
//
// Build (example): g++ -std=c++17 -Wall StudentDatabaseProcessor.cpp -lsqlite3

#include <sqlite3.h>

#include <any>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <utility>
