    // Map<String, Object>
    using StudentRecord = std::unordered_map<std::string, std::any>;

    explicit StudentDatabaseProcessor(std::string databaseName)
        : databaseName_(std::move(databaseName)) {}

    void createStudentTable() {
        const std::string createTableQuery =
            "CREATE TABLE IF NOT EXISTS students ("
            "id INTEGER PRIMARY KEY AUTOINCREMENT, "
            "name TEXT, "
            "age INTEGER, "
            "gender TEXT, "
            "grade INTEGER"
            ")";
        try {
            SqliteConnection conn = getConnection();
            SqliteStatement stmt(conn.handle(), createTableQuery);
            if (sqlite3_step(stmt.handle()) != SQLITE_DONE) {
                throw SQLException(std::string("SQL error: ") +
                                   sqlite3_errmsg(conn.handle()));
            }
        } catch (const SQLException& e) {
            e.printStackTrace();
        }
    }

    void insertStudent(const StudentData& studentData) {
        const std::string insertQuery =
            "INSERT INTO students (name, age, gender, grade) VALUES (?, ?, ?, ?)";
        try {
            SqliteConnection conn = getConnection();
            SqliteStatement pstmt(conn.handle(), insertQuery);
            sqlite3_stmt* stmt = pstmt.handle();
            if (sqlite3_bind_text(stmt, 1, studentData.getName().c_str(), -1,
                                  SQLITE_TRANSIENT) != SQLITE_OK ||
