                                  SQLITE_TRANSIENT) != SQLITE_OK ||
                sqlite3_bind_int(stmt, 4, studentData.getGrade()) != SQLITE_OK) {
                throw SQLException(std::string("SQL error: ") +
                                   sqlite3_errmsg(conn.handle()));
            }
            if (sqlite3_step(stmt) != SQLITE_DONE) {
                throw SQLException(std::string("SQL error: ") +
                                   sqlite3_errmsg(conn.handle()));
            }
        } catch (const SQLException& e) {
            e.printStackTrace();
        }
    }

    std::vector<StudentRecord> searchStudentByName(const std::string& name) {
        const std::string selectQuery = "SELECT * FROM students WHERE name = ?";
        std::vector<StudentRecord> result;
        try {
            SqliteConnection conn = getConnection();
            SqliteStatement pstmt(conn.handle(), selectQuery);
            sqlite3_stmt* stmt = pstmt.handle();
            if (sqlite3_bind_text(stmt, 1, name.c_str(), -1,
                                  SQLITE_TRANSIENT) != SQLITE_OK) { // 设置查询参数
                throw SQLException(std::string("SQL error: ") +
                                   sqlite3_errmsg(conn.handle()));
            }
            // The prepared statement doubles as the ResultSet; RAII releases
            // it automatically (try-with-resources equivalent).
            int rc = sqlite3_step(stmt);
            while (rc == SQLITE_ROW) {
                StudentRecord student;
                student["id"] =
                    sqlite3_column_int(stmt, columnIndexByName(stmt, "id"));
                student["name"] =
