static std::string javaDoubleToString(double d) {
    if (std::isnan(d)) return "NaN";
    if (std::isinf(d)) return d > 0 ? "Infinity" : "-Infinity";
    bool neg = std::signbit(d);
    if (d == 0.0) return neg ? "-0.0" : "0.0";

    char buf[64];
    auto res = std::to_chars(buf, buf + sizeof(buf), std::abs(d), std::chars_format::scientific);
    std::string sci(buf, res.ptr); // e.g. "1.025e+01"
    // parse
    size_t epos = sci.find('e');
    std::string mant = sci.substr(0, epos); // "1.025"
    int exp = std::stoi(sci.substr(epos + 1));
    std::string digits = mant; // remove '.'
    size_t dot = digits.find('.');
    if (dot != std::string::npos) digits.erase(dot, 1);
    // digits = "1025", exp = 1 → value = 1.025e1
    // digits count n; leading digit nonzero (since scientific normalized)

    std::string sign = neg ? "-" : "";
    std::string out;
    if (exp >= -3 && exp < 7) {
        // plain
        int n = (int)digits.size();
        if (exp >= 0) {
            if (n > exp + 1) {
                out = digits.substr(0, exp + 1) + "." + digits.substr(exp + 1);
            } else {
                out = digits + std::string(exp + 1 - n, '0') + ".0";
            }
        } else {
            // exp < 0: 0.00ddd
            out = "0." + std::string(-exp - 1, '0') + digits;
        }
    } else {
        // scientific
        out = digits.substr(0, 1) + "." + (digits.size() > 1 ? digits.substr(1) : "0") + "E" + std::to_string(exp);
    }
    return sign + out;
}
