class PreparedStatement {
public:
    PreparedStatement(sqlite3* db, const std::string& sql) : db_(db) {
        if (sqlite3_prepare_v2(db_, sql.c_str(), -1, &stmt_, nullptr) != SQLITE_OK) {
            const std::string msg = sqlite3_errmsg(db_);
            stmt_ = nullptr;
            throw SQLException(msg);
        }
    }

    ~PreparedStatement() {
        if (stmt_ != nullptr) {
            sqlite3_finalize(stmt_);
        }
    }

    PreparedStatement(const PreparedStatement&) = delete;
    PreparedStatement& operator=(const PreparedStatement&) = delete;

    // pstmt.setString(index, value)
    void setString(int index, const std::string& value) {
        if (sqlite3_bind_text(stmt_, index, value.c_str(), static_cast<int>(value.size()), SQLITE_TRANSIENT) != SQLITE_OK) {
            throw SQLException(sqlite3_errmsg(db_));
        }
    }

    // pstmt.execute() / first half of executeQuery(): runs the statement.
    // Returns true if a result row is available (i.e. rs.next() succeeded).
    bool next() {
        const int rc = sqlite3_step(stmt_);
        if (rc != SQLITE_ROW && rc != SQLITE_DONE) {
            throw SQLException(sqlite3_errmsg(db_));
        }
        return rc == SQLITE_ROW;
    }

    void executeUpdate() {
        const int rc = sqlite3_step(stmt_);
        if (rc != SQLITE_DONE && rc != SQLITE_ROW) {
            throw SQLException(sqlite3_errmsg(db_));
        }
    }

    // rs.getString(columnLabel)
    std::string getString(const std::string& columnLabel) const {
        const int index = columnIndex(columnLabel);
        if (index < 0) {
            throw SQLException("column not found: " + columnLabel); // SQLException in Java
        }
        const unsigned char* text = sqlite3_column_text(stmt_, index);
        if (text == nullptr) {
            // Java returns null here; string concatenation renders it as "null".
            return "null";
        }
        return std::string(reinterpret_cast<const char*>(text));
    }

private:
    int columnIndex(const std::string& columnLabel) const {
        const int n = sqlite3_column_count(stmt_);
        for (int i = 0; i < n; ++i) {
            const char* name = sqlite3_column_name(stmt_, i);
            if (name != nullptr && columnLabel == name) {
                return i;
            }
        }
        return -1;
    }

    sqlite3* db_;
    sqlite3_stmt* stmt_ = nullptr;
};
```

