namespace {
// Java's String.split(" ") semantics: split on every space, then drop trailing
// empty tokens (a string with no spaces yields the whole string, even if empty).
std::vector<std::string> javaSplit(const std::string& s, char delimiter) {
    std::vector<std::string> parts;
    size_t start = 0;
    bool sawDelimiter = false;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == delimiter) {
            parts.push_back(s.substr(start, i - start));
            start = i + 1;
            sawDelimiter = true;
        }
    }
    if (!sawDelimiter) {
        parts.push_back(s);
        return parts;
    }
    parts.push_back(s.substr(start));
    while (!parts.empty() && parts.back().empty()) {
        parts.pop_back();
    }
    return parts;
}

bool endsWith(const std::string& s, const std::string& suffix) {
    return s.size() >= suffix.size() &&
