class Logger {
public:
    enum class Level { Severe, Warning, Info };

    explicit Logger(std::string name) : name_(std::move(name)) {}

    static Logger getLogger(const std::string& name) { return Logger(name); }

    void info(const std::string& message) const { log(Level::Info, message, nullptr); }
    void warning(const std::string& message) const { log(Level::Warning, message, nullptr); }
    void severe(const std::string& message) const { log(Level::Severe, message, nullptr); }
    void severe(const std::string& message, const std::exception& error) const {
        log(Level::Severe, message, &error);
    }

private:
    static const char* levelName(Level level) {
        switch (level) {
            case Level::Severe:   return "SEVERE";
            case Level::Warning:  return "WARNING";
            case Level::Info:     return "INFO";
        }
        return "";
    }

    void log(Level level, const std::string& message, const std::exception* error) const {
        // java.util.logging's default setup: ConsoleHandler on System.err,
        // default level INFO -> SEVERE/WARNING/INFO all pass through.
        std::time_t now = std::time(nullptr);
        char timestamp[64];
        std::strftime(timestamp, sizeof(timestamp), "%b %d, %Y %I:%M:%S %p",
                      std::localtime(&now));
        std::cerr << timestamp << ' ' << name_ << '\n'
                  << levelName(level) << ": " << message << '\n';
        if (error != nullptr) {
            // Stands in for JUL printing the exception's stack trace.
            std::cerr << error->what() << '\n';
        }
        std::cerr.flush();
    }

    std::string name_;
};
