/*
# This is a class as an student assessment system, which supports add student,
# add course score, calculate GPA, and other functions for students and courses.
*/
class AssessmentSystem {
public:
    // A recorded course score; a score of None is represented by std::nullopt.
    struct CourseScore {
        std::string course;
        std::optional<int> score;
    };

    // A student record; equivalent to the Python dict
    // {'name': ..., 'grade': ..., 'major': ..., 'courses': {...}}
    struct Student {
        std::string name;
        int grade;
        std::string major;
        std::vector<CourseScore> courses;
    };

    // Python: self.students = {}  (insertion-ordered dict name -> student record)
    std::vector<Student> students;

    AssessmentSystem() = default;

    // Add a new student into students.
    void add_student(const std::string& name, int grade, const std::string& major) {
        for (Student& student : students) {
            if (student.name == name) {
                // Re-assigning an existing key keeps its position in a Python dict.
                student.grade = grade;
                student.major = major;
                student.courses.clear();
                return;
            }
        }
        students.push_back(Student{name, grade, major, {}});
    }

    // Add score of specific course for an existing student (no-op otherwise).
    void add_course_score(const std::string& name, const std::string& course,
                          std::optional<int> score) {
        Student* student = find_student(name);
        if (student == nullptr) {
            return;  // Python: silently does nothing if the name is unknown.
        }
        for (CourseScore& cs : student->courses) {
            if (cs.course == course) {
                cs.score = score;  // Re-assigning keeps the course's position.
                return;
            }
        }
        student->courses.push_back(CourseScore{course, score});
    }

    // Get average grade of one student; std::nullopt stands for None.
    std::optional<double> get_gpa(const std::string& name) {
        const Student* student = find_student(name);
        if (student == nullptr || student->courses.empty()) {
            return std::nullopt;
        }
        long long total = 0;
        for (const CourseScore& cs : student->courses) {
            if (!cs.score.has_value()) {
                // Python: sum() over a value of None raises TypeError.
                throw std::runtime_error(
                    "TypeError: unsupported operand type(s) for +: 'int' and 'NoneType'");
            }
            total += *cs.score;
        }
        return static_cast<double>(total) /
               static_cast<double>(student->courses.size());
    }

    // Get all students who have any score below 60 (in insertion order).
    std::vector<std::string> get_all_students_with_fail_course() {
        std::vector<std::string> failed;
        for (const Student& student : students) {
            for (const CourseScore& cs : student.courses) {
                if (!cs.score.has_value()) {
                    // Python: None < 60 raises TypeError.
                    throw std::runtime_error(
                        "TypeError: '<' not supported between instances of "
                        "'NoneType' and 'int'");
                }
                if (*cs.score < 60) {
                    failed.push_back(student.name);
                    break;
                }
            }
        }
        return failed;
    }

    // Get the average score of a specific course; std::nullopt if nobody has
    // a (non-None) record for it.
    std::optional<double> get_course_average(const std::string& course) {
        long long total = 0;
        std::size_t count = 0;
        for (const Student& student : students) {
            const std::optional<int>* score = find_course(student, course);
            if (score != nullptr && score->has_value()) {
                total += **score;
                ++count;
            }
        }
        if (count > 0) {
            return static_cast<double>(total) / static_cast<double>(count);
        }
        return std::nullopt;
    }

    // Find the student with the highest GPA (first one in insertion order on
    // the way up); std::nullopt if there is none with GPA > 0.
    std::optional<std::string> get_top_student() {
        std::optional<std::string> top_student;
        double top_gpa = 0;  // Python: top_gpa = 0
        for (const Student& student : students) {
            std::optional<double> gpa = get_gpa(student.name);
            if (gpa.has_value() && *gpa > top_gpa) {
                top_gpa = *gpa;
                top_student = student.name;
            }
        }
        return top_student;
    }

private:
    Student* find_student(const std::string& name) {
        for (Student& student : students) {
            if (student.name == name) {
                return &student;
            }
        }
        return nullptr;
    }

    const Student* find_student(const std::string& name) const {
        for (const Student& student : students) {
            if (student.name == name) {
                return &student;
            }
        }
        return nullptr;
    }

    static const std::optional<int>* find_course(const Student& student,
                                                 const std::string& course) {
        for (const CourseScore& cs : student.courses) {
            if (cs.course == course) {
                return &cs.score;
            }
        }
        return nullptr;
    }
};
