class DatabaseProcessor {
public:
    // A value in a data row: text (str) or integer (int), as in Python.
    using Value = std::variant<std::string, long long>;
    // One row of data: equivalent of a Python dict {'name': ..., 'age': ...}.
    using Row = std::map<std::string, Value>;
    // One row of a search result: (id, name, age), e.g. (1, "John", 25).
    using ResultRow = std::tuple<long long, std::string, long long>;

    explicit DatabaseProcessor(std::string database_name)
        : database_name_(std::move(database_name)) {}

    // Create a new table in the database if it doesn't exist.
    // id (INTEGER) is the PRIMARY KEY, key1 is TEXT, key2 is INTEGER.
    void create_table(const std::string& table_name,
                      const std::string& key1,
                      const std::string& key2) {
        Connection conn(database_name_);
        conn.execute("CREATE TABLE IF NOT EXISTS " + table_name +
                     " (id INTEGER PRIMARY KEY, " + key1 + " TEXT, " +
                     key2 + " INTEGER)");
    }

    // Insert data into the specified table in the database.
    // data: a list of dictionaries; each dictionary represents a row.
    void insert_into_database(const std::string& table_name,
                              const std::vector<Row>& data) {
        Connection conn(database_name_);
        // sqlite3 in Python runs DML inside a transaction that is only
        // committed by conn.commit(); replicate that so a failure midway
        // leaves no partial inserts.
        conn.execute("BEGIN");
        const std::string query =
            "INSERT INTO " + table_name + " (name, age) VALUES (?, ?)";
        Statement stmt(conn.get(), query);
        for (const Row& item : data) {
            sqlite3_reset(stmt.get());
            const Value& name = item.at("name");  // raises like KeyError
            const Value& age = item.at("age");
            bind(stmt.get(), 1, name);
            bind(stmt.get(), 2, age);
            if (sqlite3_step(stmt.get()) != SQLITE_DONE) {
                throw std::runtime_error(sqlite3_errmsg(conn.get()));
            }
        }
        conn.execute("COMMIT");
    }
