```cpp
#include <cstdio>
#include <map>
#include <string>
#include <variant>
#include <stdexcept>
#include <algorithm>

class BinaryDataProcessor {
public:
    std::string binary_string;

    explicit BinaryDataProcessor(const std::string& binary_string_)
        : binary_string(binary_string_) {
        clean_non_binary_chars();
    }

    // Clean the binary string by removing all non 0 or 1 characters.
    void clean_non_binary_chars() {
        std::string cleaned;
        cleaned.reserve(binary_string.size());
        for (char c : binary_string) {
            if (c == '0' || c == '1') {
                cleaned.push_back(c);
            }
        }
        binary_string = std::move(cleaned);
    }

    // Calculate the binary string information: percentage of 0s and 1s and total bit length.
    std::map<std::string, std::variant<double, int>> calculate_binary_info() const {
        const int zeroes_count = static_cast<int>(std::count(binary_string.begin(), binary_string.end(), '0'));
        const int ones_count = static_cast<int>(std::count(binary_string.begin(), binary_string.end(), '1'));
        const int total_length = static_cast<int>(binary_string.size());

        if (total_length == 0) {
            throw std::runtime_error("division by zero");
        }

        const double zeroes_percentage = static_cast<double>(zeroes_count) / total_length;
        const double ones_percentage = static_cast<double>(ones_count) / total_length;

        return {
            {"Zeroes", zeroes_percentage},
            {"Ones", ones_percentage},
            {"Bit length", total_length}
        };
    }

    // Convert the binary string to an ASCII string.
    std::string convert_to_ascii() const {
        const std::string byte_array = build_byte_array();
        for (std::size_t i = 0; i < byte_array.size(); ++i) {
            const unsigned char b = static_cast<unsigned char>(byte_array[i]);
            if (b > 127) {
                throw std::runtime_error("'ascii' codec can't decode byte " + hex_byte(b) +
                                         " in position " + std::to_string(i) +
                                         ": ordinal not in range(128)");
            }
        }
        return byte_array;
    }

    // Convert the binary string to a UTF-8 string.
    std::string convert_to_utf8() const {
        const std::string byte_array = build_byte_array();
        validate_utf8(byte_array);
        return byte_array;
    }

private:
    // Build the raw byte array, mirroring: int(chunk, 2) for each 8-bit chunk.
    std::string build_byte_array() const {
        std::string byte_array;
        const std::string& s = binary_string;
        for (std::size_t i = 0; i < s.size(); i += 8) {
            const std::size_t len = std::min<std::size_t>(8, s.size() - i);
            const std::string chunk = s.substr(i, len);
            const int decimal = parse_int_base2(chunk);
            if (decimal < 0 || decimal > 255) {
                throw std::invalid_argument("byte must be in range(0, 256)");
            }
            byte_array.push_back(static_cast<char>(decimal));
        }
        return byte_array;
    }

    // Emulate Python's int(s, 2).
    static int parse_int_base2(const std::string& s) {
        std::size_t begin = 0;
        std::size_t end = s.size();
        while (begin < end && is_python_space(s[begin])) ++begin;
        while (end > begin && is_python_space(s[end - 1])) --end;

        bool negative = false;
        if (begin < end && (s[begin] == '+' || s[begin] == '-')) {
            negative = (s[begin] == '-');
            ++begin;
        }
        if (end - begin >= 2 && s[begin] == '0' && (s[begin + 1] == 'b' || s[begin + 1] == 'B')) {
            begin += 2;
        }
        if (begin >= end) {
            throw std::invalid_argument("invalid literal for int() with base 2: '" + s + "'");
        }
        long long value = 0;
        for (std::size_t i = begin; i < end; ++i) {
            const char c = s[i];
            if (c != '0' && c != '1') {
                throw std::invalid_argument("invalid literal for int() with base 2: '" + s + "'");
            }
            value = value * 2 + (c - '0');
        }
        return negative ? static_cast<int>(-value) : static_cast<int>(value);
    }

    static bool is_python_space(char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
    }

    static std::string hex_byte(unsigned char b) {
        char buf[8];
        std::snprintf(buf, sizeof(buf), "0x%02x", b);
        return std::string(buf);
    }

    // Emulate Python's bytes.decode('utf-8') validation.
    static void validate_utf8(const std::string& data) {
        const std::size_t n = data.size();
        std::size_t i = 0;
        while (i < n) {
            const unsigned char b0 = static_cast<unsigned char>(data[i]);
            if (b0 <= 0x7F) {
                ++i;
                continue;
            }

            std::size_t length = 0;
            unsigned char second_lo = 0, second_hi = 0;
            if (b0 >= 0xC2 && b0 <= 0xDF) {
                length = 2; second_lo = 0x80; second_hi = 0xBF;
            } else if (b0 == 0xE0) {
                length = 3; second_lo = 0xA0; second_hi = 0xBF;
            } else if (b0 >= 0xE1 && b0 <= 0xEC) {
                length = 3; second_lo = 0x80; second_hi = 0xBF;
            } else if (b0 == 0xED) {
                length = 3; second_lo = 0x80; second_hi = 0x9F;
            } else if (b0 >= 0xEE && b0 <= 0xEF) {
                length = 3; second_lo = 0x80; second_hi = 0xBF;
            } else if (b0 == 0xF0) {
                length = 4; second_lo = 0x90; second_hi = 0xBF;
            } else if (b0 >= 0xF1 && b0 <= 0xF3) {
                length = 4; second_lo = 0x80; second_hi = 0xBF;
            } else if (b0 == 0xF4) {
                length = 4; second_lo = 0x80; second_hi = 0x8F;
            } else {
                throw std::runtime_error("'utf-8' codec can't decode byte " + hex_byte(b0) +
                                         " in position " + std::to_string(i) + ": invalid start byte");
            }

            for (std::size_t k = 1; k < length; ++k) {
                if (i + k >= n) {
                    throw std::runtime_error("'utf-8' codec can't decode byte " + hex_byte(b0) +
                                             " in position " + std::to_string(i) +
                                             ": unexpected end of data");
                }
                const unsigned char bk = static_cast<unsigned char>(data[i + k]);
                const bool in_range = (k == 1) ? (bk >= second_lo && bk <= second_hi)
                                               : (bk >= 0x80 && bk <= 0xBF);
                if (!in_range) {
                    throw std::runtime_error("'utf-8' codec can't decode byte " + hex_byte(bk) +
                                             " in position " + std::to_string(i + k) +
                                             ": invalid continuation byte");
                }
            }
            i += length;
        }
    }
};
