```cpp
// This is a utility class for managing and manipulating Cookies, including
// methods for retrieving, saving, and setting Cookies data.
//
// Requires the nlohmann/json library (https://github.com/nlohmann/json).

#include <fstream>
#include <stdexcept>
#include <string>
#include <filesystem>

#include <nlohmann/json.hpp>

// ordered_json preserves insertion order of keys, exactly like Python dicts.
using json = nlohmann::ordered_json;

class CookiesUtil {
public:
    std::string cookies_file;
    json cookies;  // null until get_cookies() is called (mirrors Python's None)

    // Initializes the CookiesUtil with the specified cookies file.
    explicit CookiesUtil(const std::string& cookies_file_)
        : cookies_file(cookies_file_), cookies(nullptr) {}

    // Gets the cookies from the specified response and saves them to cookies_file.
    void get_cookies(const json& reponse) {
        cookies = reponse.at("cookies");  // throws (KeyError analogue) if missing
        _save_cookies();
    }

    // Loads the cookies from the cookies_file.
    json load_cookies() const {
        std::ifstream file(cookies_file);
        if (!file.is_open()) {
            // FileNotFoundError branch: only a genuinely missing path yields {}
            std::error_code ec;
            if (!std::filesystem::exists(cookies_file, ec) || ec) {
                return json::object();
            }
            // Any other open failure (e.g. permission denied) propagates, like Python.
            throw std::runtime_error("Failed to open cookies file: " + cookies_file);
        }
        // Throws on malformed JSON, like Python's json.load raising JSONDecodeError.
        return json::parse(file);
    }

    // Saves the cookies to the cookies_file; returns true on success, false otherwise.
    bool _save_cookies() {
        try {
            std::ofstream file(cookies_file);
            if (!file.is_open()) {
                throw std::runtime_error("Failed to open cookies file: " + cookies_file);
            }
            file << python_json_dump(cookies);
            if (!file) {
                throw std::runtime_error("Failed to write cookies file: " + cookies_file);
            }
            return true;
        } catch (...) {
            return false;
        }
    }

    // Sets request["cookies"] to "key1=value1; key2=value2; ..." from the stored cookies.
    void set_cookies(json& request) const {
        if (!cookies.is_object()) {
            // Python would raise AttributeError on None.items() (or non-dict .items()).
            throw std::runtime_error("'NoneType' object has no attribute 'items'");
        }
        std::string joined;
        for (auto it = cookies.begin(); it != cookies.end(); ++it) {
            if (!joined.empty()) {
                joined += "; ";
            }
            joined += it.key() + "=" + python_str(it.value());
        }
        request["cookies"] = joined;
    }

private:
    // Serializes like Python's json.dump with default separators (", " / ": ").
    static std::string python_json_dump(const json& j) {
        switch (j.type()) {
            case json::value_t::object: {
                std::string out = "{";
                bool first = true;
                for (auto it = j.begin(); it != j.end(); ++it) {
                    if (!first) out += ", ";
                    first = false;
                    out += json(it.key()).dump() + ": " + python_json_dump(it.value());
                }
                return out + "}";
            }
            case json::value_t::array: {
                std::string out = "[";
                bool first = true;
                for (const auto& element : j) {
                    if (!first) out += ", ";
                    first = false;
                    out += python_json_dump(element);
                }
                return out + "]";
            }
            default:
                return j.dump();
        }
    }

    // Mimics Python str() applied to a JSON value (used by the f-string in set_cookies).
    static std::string python_str(const json& v) {
