                int base = static_cast<int>(std::tolower(ch)) - 'a';
                int enc = ((base + shift) % 26 + 26) % 26 + 'a';
                char encrypted_char = static_cast<char>(enc);
                encrypted_text += std::isupper(ch) ? static_cast<char>(std::toupper(static_cast<unsigned char>(encrypted_char))) : encrypted_char;
                ++key_index;
            } else {
                encrypted_text += static_cast<char>(ch);
            }
        }
        return encrypted_text;
    }

    std::string rail_fence_cipher(const std::string& plain_text, int rails) const {
        const std::size_t cols = plain_text.size();
        std::vector<std::vector<char>> fence;
        if (rails > 0) {
            fence.assign(static_cast<std::size_t>(rails), std::vector<char>(cols, '\n'));
        }
        int direction = -1;
        std::size_t row = 0, col = 0;

        for (char c : plain_text) {
            if (row == 0 || row == static_cast<std::size_t>(rails) - 1) {
