        try {
            std::ofstream file(file_name);
            if (!file.is_open()) {
                return 0;
            }
            for (const auto& row : data) {
                for (size_t i = 0; i < row.size(); i++) {
                    if (i > 0) file << ",";
                    file << row[i];
                }
                file << "\n";
            }
            file.close();
            return 1;
        } catch (...) {
            return 0;
        }
    }

