class EightPuzzle {
public:
    using State = std::vector<std::vector<int>>;
    using Position = std::pair<int, int>;

    /**
     * Initializes the initial state of the Eight Puzzle Game (initial_state)
     * and sets the goal state. The board size is 3x3.
     */
    explicit EightPuzzle(State initial_state)
        : initial_state(std::move(initial_state)),
          goal_state{{1, 2, 3}, {4, 5, 6}, {7, 8, 0}} {}

    /**
     * Finds the blank position of the current state (the 0 element).
     * Returns std::nullopt when the state contains no blank tile,
     * mirroring the Python version returning None.
     */
    std::optional<Position> find_blank(const State& state) const {
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (state.at(i).at(j) == 0) {
                    return std::make_pair(i, j);
                }
            }
        }
        return std::nullopt;
    }

    /**
     * Finds the blank block, then moves the board in the given direction.
     * Returns the state after moving (the input state is left untouched).
     * Unknown directions leave the copied state unchanged, just like Python.
     */
    State move(const State& state, const std::string& direction) const {
        const std::optional<Position> blank = find_blank(state);
        if (!blank.has_value()) {
            // Python: `i, j = self.find_blank(state)` raises TypeError
            // when trying to unpack None.
            throw std::runtime_error("cannot unpack non-iterable NoneType");
