        const int i = blank->first;
        const int j = blank->second;

        State new_state = state;  // [row[:] for row in state]

        if (direction == "up") {
            std::swap(new_state.at(py_index(i - 1, new_state.size())).at(j),
                      new_state.at(i).at(j));
        } else if (direction == "down") {
            std::swap(new_state.at(py_index(i + 1, new_state.size())).at(j),
                      new_state.at(i).at(j));
        } else if (direction == "left") {
            std::swap(new_state.at(i).at(py_index(j - 1, new_state.at(i).size())),
                      new_state.at(i).at(j));
        } else if (direction == "right") {
            std::swap(new_state.at(i).at(py_index(j + 1, new_state.at(i).size())),
                      new_state.at(i).at(j));
        }

        return new_state;
    }
