```cpp
/*
 * A tool class for IP addresses: validate IPv4/IPv6 addresses and
 * resolve the hostname associated with a given IP address.
 *
 * Translation notes (behavior kept identical to the Python original):
 *  - is_valid_ipv4 / is_valid_ipv6 mirror socket.inet_pton(): the exact same
 *    libc resolver function is used, so acceptance/rejection of any input
 *    (including edge cases such as leading zeros, empty strings, extra
 *    whitespace, etc.) matches Python byte for byte.
 *  - get_hostname mirrors socket.gethostbyaddr():
 *      * a non-numeric / malformed address makes Python raise socket.gaierror
 *        (which the Python code does NOT catch) -> we throw std::runtime_error;
 *      * a syntactically valid address whose reverse lookup fails raises
 *        socket.herror, which the Python code catches -> we return std::nullopt
 *        (the C++ equivalent of None);
 *      * otherwise the primary hostname (element [0] of Python's result tuple)
 *        is returned.
 */

#include <string>
#include <optional>
#include <stdexcept>

#ifdef _WIN32
#  include <winsock2.h>
#  include <ws2tcpip.h>
#  pragma comment(lib, "ws2_32.lib")
#else
#  include <sys/socket.h>
#  include <arpa/inet.h>
#  include <netdb.h>
#  include <netinet/in.h>
#  include <sys/types.h>
#endif

class IpUtil {
public:
    // Check if the given IP address is a valid IPv4 address.
    // Returns true if valid, false otherwise.
    static bool is_valid_ipv4(const std::string& ip_address) {
        ensure_winsock_initialized();
        struct in_addr addr;
        // inet_pton returns 1 on success, 0 for a malformed address and -1 on
        // error; Python turns both failure modes into "False" (socket.error).
        return inet_pton(AF_INET, ip_address.c_str(), &addr) == 1;
    }

    // Check if the given IP address is a valid IPv6 address.
    // Returns true if valid, false otherwise.
    static bool is_valid_ipv6(const std::string& ip_address) {
        ensure_winsock_initialized();
        struct in6_addr addr;
        return inet_pton(AF_INET6, ip_address.c_str(), &addr) == 1;
    }

    // Get the hostname associated with the given IP address.
    // Returns the hostname, or std::nullopt (Python's None) when the reverse
    // lookup fails (socket.herror in Python).
    static std::optional<std::string> get_hostname(const std::string& ip_address) {
        ensure_winsock_initialized();

        // Python 3's socket.gethostbyaddr() first parses the argument as a
        // numeric address (getaddrinfo with AI_NUMERICHOST). A malformed or
        // non-numeric argument raises socket.gaierror, which is *not* caught
        // by the Python code, so propagate it as an exception here as well.
        const void* raw_addr = nullptr;
        socklen_t raw_len = 0;
        int family = AF_UNSPEC;

        struct in_addr addr4;
        struct in6_addr addr6;
        if (inet_pton(AF_INET, ip_address.c_str(), &addr4) == 1) {
            raw_addr = &addr4;
            raw_len = static_cast<socklen_t>(sizeof(addr4));
            family = AF_INET;
        } else if (inet_pton(AF_INET6, ip_address.c_str(), &addr6) == 1) {
            raw_addr = &addr6;
            raw_len = static_cast<socklen_t>(sizeof(addr6));
            family = AF_INET6;
        } else {
            throw std::runtime_error(
                "socket.gaierror: [Errno -2] Name or service not known");
        }

        // Reverse lookup, equivalent to socket.gethostbyaddr()[0].
        struct hostent* he = gethostbyaddr(
#ifdef _WIN32
            static_cast<const char*>(raw_addr),  // Windows takes a char*
#else
            raw_addr,
#endif
            static_cast<int>(raw_len), family);

        if (he == nullptr || he->h_name == nullptr) {
            // Python catches socket.herror here and returns None.
            return std::nullopt;
        }
        return std::string(he->h_name);
    }

private:
    // On Windows, the socket subsystem must be initialized once before any
    // socket function can be used (Python does this implicitly).
    static void ensure_winsock_initialized() {
#ifdef _WIN32
        static const bool initialized = []() {
            WSADATA data;
            return WSAStartup(MAKEWORD(2, 2), &data) == 0;
        }();
        (void)initialized;
#endif
    }
};
```

