class MusicPlayer {
public:
    std::vector<std::string> playlist;
    std::optional<std::string> current_song;
    int volume;

    MusicPlayer()
        : playlist(),
          current_song(std::nullopt),
          volume(50) {}

    // Adds a song to the playlist.
    void add_song(const std::string& song) {
        playlist.push_back(song);
    }

    // Removes a song from the playlist.
    void remove_song(const std::string& song) {
        auto it = std::find(playlist.begin(), playlist.end(), song);
        if (it != playlist.end()) {
            playlist.erase(it);
            if (current_song.has_value() && *current_song == song) {
                stop();
            }
        }
    }

    // Plays the current song in the playlist.
    // Returns the first song of the playlist if there is a (truthy) current
    // song, std::nullopt otherwise (False when there is no current song,
    // None when the playlist is empty).
    std::optional<std::string> play() {
        if (!playlist.empty() && current_song_has_value()) {
            return playlist[0];
        } else if (!playlist.empty()) {
            return std::nullopt;
        }
        return std::nullopt;
    }

    // Stops the current song.
    bool stop() {
        if (current_song_has_value()) {
            current_song = std::nullopt;
            return true;
        }
        return false;
    }

    // Switches to the next song in the playlist.
    bool switch_song() {
        if (current_song_has_value()) {
            std::size_t current_index = index_of_current_song();
            if (current_index + 1 < playlist.size()) {
                current_song = playlist[current_index + 1];
                return true;
            }
            return false;
        }
        return false;
    }

    // Switches to the previous song in the playlist.
    bool previous_song() {
        if (current_song_has_value()) {
            std::size_t current_index = index_of_current_song();
            if (current_index > 0) {
                current_song = playlist[current_index - 1];
                return true;
            }
            return false;
        }
        return false;
    }

    // Sets the volume if it is between 0 and 100 (inclusive).
    bool set_volume(int volume_) {
        if (volume_ >= 0 && volume_ <= 100) {
            volume = volume_;
            return true;
        }
        return false;
    }

    // Shuffles the playlist.
    bool shuffle() {
        if (!playlist.empty()) {
            std::random_device rd;
            std::mt19937 g(rd());
            std::shuffle(playlist.begin(), playlist.end(), g);
            return true;
        }
        return false;
    }

private:
    // Mirrors Python truthiness of self.current_song (None or "" are falsy).
    bool current_song_has_value() const {
        return current_song.has_value() && !current_song->empty();
    }

    // Mirrors list.index(): throws if the current song is not in the playlist.
    std::size_t index_of_current_song() const {
        auto it = std::find(playlist.begin(), playlist.end(), *current_song);
        if (it == playlist.end()) {
            throw std::invalid_argument("'" + *current_song + "' is not in list");
        }
        return static_cast<std::size_t>(it - playlist.begin());
    }
};
