class NumericEntityUnescaper {
public:
    NumericEntityUnescaper() {}

    std::string replace(const std::string& str) const {
        std::string out;
        size_t pos = 0;
        size_t length = str.length();

        while (pos + 2 < length) {
            if (str[pos] == '&' && str[pos + 1] == '#') {
                size_t start = pos + 2;
                bool is_hex = false;
                char first_char = str[start];

                if (first_char == 'x' || first_char == 'X') {
                    start += 1;
                    is_hex = true;
                }

                if (start == length) {
                    return out;
                }

                size_t end = start;
                while (end < length && is_hex_char(str[end])) {
                    end += 1;
                }

                if (end < length && str[end] == ';') {
                    // Python: int(string[start:end], 16 if is_hex else 10)
                    // The slice contains only hex-digit characters here.
                    // int() fails when the slice is empty, or (base 10) when
                    // it contains letters -> return what has been collected.
                    bool parseable = (end > start);
                    if (parseable && !is_hex) {
                        for (size_t i = start; i < end; ++i) {
                            if (str[i] < '0' || str[i] > '9') {
                                parseable = false;
                                break;
                            }
                        }
                    }
                    if (!parseable) {
                        return out;
                    }

                    unsigned long long entity_value = 0;
                    bool out_of_range = false;
                    unsigned base = is_hex ? 16u : 10u;
                    for (size_t i = start; i < end; ++i) {
                        int d;
                        char c = str[i];
                        if (c >= '0' && c <= '9') {
                            d = c - '0';
                        } else if (c >= 'a' && c <= 'f') {
                            d = c - 'a' + 10;
                        } else { // 'A'..'F'
                            d = c - 'A' + 10;
                        }
                        entity_value = entity_value * base + static_cast<unsigned long long>(d);
                        if (entity_value > 0x10FFFFull) {
                            out_of_range = true;
                            break;
                        }
                    }
                    if (out_of_range || entity_value > 0x10FFFFull) {
                        // Python: chr() raises ValueError for such values
                        // (this exception is not caught by replace()).
                        throw std::out_of_range(
                            "chr() arg not in range(0x110000)");
                    }

                    append_code_point(out, static_cast<std::uint32_t>(entity_value));
                    pos = end + 1;
                    continue;
                }
            }

            out += str[pos];
            pos += 1;
        }

        return out;
    }

    static bool is_hex_char(char c) {
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') ||
               (c >= 'A' && c <= 'F');
    }

private:
    static void append_code_point(std::string& out, std::uint32_t cp) {
        if (cp < 0x80u) {
            out += static_cast<char>(cp & 0x7Fu);
        } else if (cp < 0x800u) {
            out += static_cast<char>(0xC0u | (cp >> 6));
