class TicTacToe {
public:
    // 3 rows x N columns board of ' ' (empty) cells; current player starts as 'X'.
    std::vector<std::vector<char>> board;
    char current_player;

    explicit TicTacToe(int N = 3)
        : board(3, std::vector<char>(N, ' ')), current_player('X') {}

    // Place the current player's mark at (row, col); switch player on success.
    // Returns true on success, false if the cell is already occupied.
    // Throws std::out_of_range for invalid indices (mirrors Python's IndexError).
    bool make_move(int row, int col) {
        if (board.at(row).at(col) == ' ') {
            board[row][col] = current_player;
            current_player = (current_player == 'X') ? 'O' : 'X';
            return true;
        }
        return false;
    }

