                board.at(2).at(col) != ' ') {
                return board[0][col];
            }
        }
        if (board.at(0).at(0) == board.at(1).at(1) &&
            board.at(1).at(1) == board.at(2).at(2) &&
            board.at(2).at(2) != ' ') {
            return board[0][0];
        }
        if (board.at(0).at(2) == board.at(1).at(1) &&
            board.at(1).at(1) == board.at(2).at(0) &&
            board.at(2).at(0) != ' ') {
            return board[0][2];
        }
        return std::nullopt;
    }

    // Returns true if the board is completely filled.
    bool is_board_full() const {
        for (const auto& row : board) {
            for (char cell : row) {
                if (cell == ' ') {
                    return false;
                }
            }
        }
        return true;
    }
};
```

