        std::string::size_type query_start = url.find("?");
        std::string::size_type fragment_start = url.find("#");
        if (query_start != std::string::npos) {
            // Python: query_string = self.url[query_start + 1 : fragment_start]
            // Note: when there is no '#', fragment_start is -1 in Python, which
            // means the slice end is len(url) - 1 (the last character is excluded).
