                url,
                static_cast<long long>(query_start) + 1,
                fragment_start == std::string::npos ? -1 : static_cast<long long>(fragment_start));
            std::map<std::string, std::string> params;
            if (!query_string.empty()) {
                std::vector<std::string> param_pairs = py_split(query_string, "&");
                for (const std::string& pair : param_pairs) {
                    std::vector<std::string> key_value = py_split(pair, "=");
                    if (key_value.size() == 2) {
                        params[key_value[0]] = key_value[1];
                    }
                }
            }
            return params;
        }
        return std::nullopt;
    }

    /**
     * Get the fragment after '#' in the URL.
