    std::optional<std::string> get_fragment() const {
        std::string::size_type fragment_start = url.find("#");
        if (fragment_start != std::string::npos) {
            return url.substr(fragment_start + 1);
        }
        return std::nullopt;
    }

private:
    // Emulates Python's s[start:stop] slicing for the cases used above,
    // including negative stop values (e.g. -1 -> len - 1).
    static std::string py_slice(const std::string& s, long long start, long long stop) {
        const long long len = static_cast<long long>(s.length());
        if (start < 0) start += len;
        if (stop < 0) stop += len;
        if (start < 0) start = 0;
        if (stop < 0) stop = 0;
        if (start > len) start = len;
        if (stop > len) stop = len;
        if (start >= stop) return std::string();
        return s.substr(static_cast<size_t>(start), static_cast<size_t>(stop - start));
    }

    // Emulates Python's s.split(sep) for a non-empty separator.
    static std::vector<std::string> py_split(const std::string& s, const std::string& sep) {
        std::vector<std::string> parts;
        std::string::size_type start = 0;
        std::string::size_type pos;
        while ((pos = s.find(sep, start)) != std::string::npos) {
            parts.push_back(s.substr(start, pos - start));
            start = pos + sep.length();
        }
        parts.push_back(s.substr(start));
        return parts;
    }
};
