// Validate and re-encode: copy valid sequences, replace invalid bytes with U+FFFD
static std::string sanitize_utf8(const std::string& in) {
    std::string out;
    out.reserve(in.size());
    size_t i = 0;
    const unsigned char* p = reinterpret_cast<const unsigned char*>(in.data());
    size_t n = in.size();
    while (i < n) {
        unsigned char c = p[i];
        if (c < 0x80) { out += static_cast<char>(c); ++i; continue; }
        int len = 0;
        unsigned int cp = 0;
        if ((c & 0xE0) == 0xC0) { len = 2; cp = c & 0x1F; }
        else if ((c & 0xF0) == 0xE0) { len = 3; cp = c & 0x0F; }
        else if ((c & 0xF8) == 0xF0) { len = 4; cp = c & 0x07; }
        else { append_utf8_replacement(out); ++i; continue; }
        if (i + len > n) { append_utf8_replacement(out); ++i; continue; }
        bool ok = true;
        for (int k = 1; k < len; ++k) {
            unsigned char cc = p[i + k];
            if ((cc & 0xC0) != 0x80) { ok = false; break; }
            cp = (cp << 6) | (cc & 0x3F);
        }
        if (!ok) { append_utf8_replacement(out); ++i; continue; }
        // check overlong / range / surrogates
        bool valid = false;
        if (len == 2) valid = cp >= 0x80;
        else if (len == 3) valid = cp >= 0x800 && !(cp >= 0xD800 && cp <= 0xDFFF);
        else if (len == 4) valid = cp >= 0x10000 && cp <= 0x10FFFF;
        if (!valid) { append_utf8_replacement(out); ++i; continue; }
        // copy the sequence
        out.append(in, i, len);
        i += len;
    }
    return out;
}
