#include <sqlite3.h>

#include <cstddef>
#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

// Exception type standing in for the errors raised by Python's sqlite3 module
// (e.g. sqlite3.OperationalError / sqlite3.IntegrityError).
class SqliteError : public std::runtime_error {
public:
    explicit SqliteError(const std::string& message) : std::runtime_error(message) {}
};

// Database management class for user login verification: inserting user
// information, searching user information, deleting user information and
// validating user login.
class UserLoginDB {
public:
    // Initializes the UserLoginDB object with the specified database name.
    explicit UserLoginDB(const std::string& db_name) {
        if (sqlite3_open(db_name.c_str(), &connection_) != SQLITE_OK) {
            const std::string message = (connection_ != nullptr)
                                            ? sqlite3_errmsg(connection_)
                                            : "unable to open database file";
            close();
            throw SqliteError(message);
        }
    }

    ~UserLoginDB() { close(); }

    UserLoginDB(const UserLoginDB&) = delete;
    UserLoginDB& operator=(const UserLoginDB&) = delete;

    // Inserts a new user into the "users" table.
    void insert_user(const std::string& username, const std::string& password) {
        execute("INSERT INTO users (username, password) VALUES (?, ?)",
                {username, password});
    }

    // Searches for a user in the "users" table by username. Returns the first
    // matching row (as a vector of column values), or std::nullopt when no
    // user matches (Python's fetchone() returning None).
    std::optional<std::vector<std::string>> search_user_by_username(
        const std::string& username) const {
        sqlite3_stmt* stmt = prepare("SELECT * FROM users WHERE username = ?", {username});

        const int rc = sqlite3_step(stmt);
        if (rc == SQLITE_ROW) {
            std::vector<std::string> row;
            const int column_count = sqlite3_column_count(stmt);
            row.reserve(static_cast<std::size_t>(column_count));
            for (int i = 0; i < column_count; ++i) {
                const unsigned char* text = sqlite3_column_text(stmt, i);
                const int bytes = sqlite3_column_bytes(stmt, i);
                if (text == nullptr || bytes <= 0) {
                    row.emplace_back();
                } else {
                    row.emplace_back(reinterpret_cast<const char*>(text),
                                     static_cast<std::size_t>(bytes));
                }
            }
            sqlite3_finalize(stmt);
            return row;
        }

        const std::string message = sqlite3_errmsg(connection_);
        sqlite3_finalize(stmt);
        if (rc != SQLITE_DONE) {
            throw SqliteError(message);
        }
        return std::nullopt;
    }

    // Deletes a user from the "users" table by username.
    void delete_user_by_username(const std::string& username) {
        execute("DELETE FROM users WHERE username = ?", {username});
    }

    // Determines whether the user can log in, i.e. the user exists in the
    // database and the password is correct.
    bool validate_user_login(const std::string& username, const std::string& password) const {
        const std::optional<std::vector<std::string>> user =
            search_user_by_username(username);
        return user.has_value() && user->at(1) == password;
    }

private:
    sqlite3* connection_ = nullptr;

    void close() noexcept {
        if (connection_ != nullptr) {
            sqlite3_close(connection_);
            connection_ = nullptr;
        }
    }

    // Prepares the SQL statement and binds the given text parameters to it.
    sqlite3_stmt* prepare(const char* sql, const std::vector<std::string>& params) const {
        sqlite3_stmt* stmt = nullptr;
        if (sqlite3_prepare_v2(connection_, sql, -1, &stmt, nullptr) != SQLITE_OK) {
            // On failure *ppStmt is set to NULL, so nothing has to be freed.
            throw SqliteError(sqlite3_errmsg(connection_));
        }
        for (std::size_t i = 0; i < params.size(); ++i) {
            const int rc = sqlite3_bind_text(stmt, static_cast<int>(i) + 1,
                                             params[i].data(),
                                             static_cast<int>(params[i].size()),
                                             SQLITE_TRANSIENT);
            if (rc != SQLITE_OK) {
                const std::string message = sqlite3_errmsg(connection_);
                sqlite3_finalize(stmt);
                throw SqliteError(message);
            }
        }
        return stmt;
    }

    // Runs a modifying statement to completion. The connection runs in
    // SQLite's autocommit mode, so a successful statement is committed
    // immediately, which matches execute() followed by commit() in Python.
    void execute(const char* sql, const std::vector<std::string>& params) {
        sqlite3_stmt* stmt = prepare(sql, params);
        const int rc = sqlite3_step(stmt);
        const std::string message = sqlite3_errmsg(connection_);
        sqlite3_finalize(stmt);
        if (rc != SQLITE_DONE) {
            throw SqliteError(message);
        }
    }
};
