#include <map>
#include <optional>
#include <string>
#include <utility>
#include <variant>

/*
 * This is a class representing a weather system that provides functionality
 * to query weather information for a specific city and convert temperature
 * units between Celsius and Fahrenheit.
 *
 * Python return-value mapping for query():
 *   - False  -> bool{false}                       (city not found)
 *   - None   -> std::monostate{}                  (unrecognized target units)
 *   - tuple  -> std::pair<double, std::string>    (temperature, weather)
 */
class WeatherSystem {
public:
    // A value inside a city's record: 'temperature' is a number,
    // 'weather' and 'temperature units' are strings.
    using Value = std::variant<double, std::string>;
    using CityRecord = std::map<std::string, Value>;
    using WeatherList = std::map<std::string, CityRecord>;
    using QueryResult = std::variant<bool, std::monostate,
                                     std::pair<double, std::string>>;

    // Initialize the weather system with a city name.
    explicit WeatherSystem(std::string city) : city(std::move(city)) {}

    /*
     * Query the weather system for the weather and temperature of the city,
     * and convert the temperature units based on the input parameter.
     */
    QueryResult query(const WeatherList& weather_list,
                      const std::string& tmp_units = "celsius") {
        this->weather_list = weather_list;

        auto cityIt = this->weather_list.find(city);
        if (cityIt == this->weather_list.end()) {
            return false;  // Python: return False
        }
        const CityRecord& record = cityIt->second;

        // .at() throws std::out_of_range, mirroring Python's KeyError.
        temperature = std::get<double>(record.at("temperature"));
        weather = std::get<std::string>(record.at("weather"));

        // Cross-type comparison works like Python's != on differing types.
        const Value& units = record.at("temperature units");
        if (units != Value{tmp_units}) {
            if (tmp_units == "celsius") {
                return {std::make_pair(fahrenheit_to_celsius(), *weather)};
            } else if (tmp_units == "fahrenheit") {
                return {std::make_pair(celsius_to_fahrenheit(), *weather)};
            }
            return std::monostate{};  // Python: implicit None
        }
        return {std::make_pair(*temperature, *weather)};
    }

    // Set the city of the weather system.
    void set_city(std::string new_city) { city = std::move(new_city); }

    // Convert the temperature from Celsius to Fahrenheit.
    // Throws (like Python's TypeError on None) if no temperature is set.
    double celsius_to_fahrenheit() const {
        return (temperature.value() * 9.0 / 5.0) + 32.0;
    }

    // Convert the temperature from Fahrenheit to Celsius.
    double fahrenheit_to_celsius() const {
        return (temperature.value() - 32.0) * 5.0 / 9.0;
    }

    // Public attributes, mirroring the Python class.
    std::optional<double> temperature;      // None until queried
    std::optional<std::string> weather;     // None until queried
    std::string city;
    WeatherList weather_list;
};
