namespace {

// Minimal arbitrary-precision unsigned integer (enough for the arithmetic
// performed by Words2Numbers: multiply by a small scale, add a small value,
// add another big value, and convert to decimal string).
struct BigNum {
    std::vector<int> digits;  // little-endian decimal digits; empty == 0

    BigNum() {}

    void mul_add(unsigned long long multiplier, unsigned long long addend) {
        unsigned long long carry = addend;
        for (std::size_t i = 0; i < digits.size(); ++i) {
            unsigned long long cur = static_cast<unsigned long long>(digits[i]) * multiplier + carry;
            digits[i] = static_cast<int>(cur % 10);
            carry = cur / 10;
        }
        while (carry) {
            digits.push_back(static_cast<int>(carry % 10));
            carry /= 10;
        }
    }

    BigNum plus(const BigNum& other) const {
        BigNum r;
        r.digits = digits;
        int carry = 0;
        std::size_t n = r.digits.size() > other.digits.size() ? r.digits.size() : other.digits.size();
        r.digits.resize(n, 0);
        for (std::size_t i = 0; i < n; ++i) {
            int s = r.digits[i] + (i < other.digits.size() ? other.digits[i] : 0) + carry;
            r.digits[i] = s % 10;
            carry = s / 10;
        }
        if (carry) r.digits.push_back(carry);
        return r;
    }

    std::string str() const {
        if (digits.empty()) return "0";
        std::string s;
        s.reserve(digits.size());
        for (std::size_t i = digits.size(); i-- > 0;)
            s.push_back(static_cast<char>('0' + digits[i]));
        return s;
    }
};

std::vector<std::string> split_words(const std::string& s) {
    std::vector<std::string> out;
    std::istringstream iss(s);
    std::string w;
    while (iss >> w) out.push_back(w);
    return out;
}

bool ends_with(const std::string& word, const std::string& ending) {
    return word.size() >= ending.size() &&
           word.compare(word.size() - ending.size(), ending.size(), ending) == 0;
}

}  // namespace

class Words2Numbers {
public:
    Words2Numbers() {
        units = {
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        };
        tens = {"", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"};
        scales = {"hundred", "thousand", "million", "billion", "trillion"};

        numwords["and"] = std::make_pair(1LL, 0LL);
        for (std::size_t idx = 0; idx < units.size(); ++idx)
            numwords[units[idx]] = std::make_pair(1LL, static_cast<long long>(idx));
        for (std::size_t idx = 0; idx < tens.size(); ++idx)
            numwords[tens[idx]] = std::make_pair(1LL, static_cast<long long>(idx) * 10LL);
        for (std::size_t idx = 0; idx < scales.size(); ++idx) {
            long long e = static_cast<long long>(idx) * 3;
            if (e == 0) e = 2;  // Python: idx * 3 or 2
            long long scale = 1;
            for (long long i = 0; i < e; ++i) scale *= 10;
            numwords[scales[idx]] = std::make_pair(scale, 0LL);
        }

        ordinal_words["first"] = 1;
        ordinal_words["second"] = 2;
        ordinal_words["third"] = 3;
        ordinal_words["fifth"] = 5;
        ordinal_words["eighth"] = 8;
        ordinal_words["ninth"] = 9;
        ordinal_words["twelfth"] = 12;

        ordinal_endings.push_back(std::make_pair(std::string("ieth"), std::string("y")));
        ordinal_endings.push_back(std::make_pair(std::string("th"), std::string("")));
    }

    std::string text2int(const std::string& input) const {
        std::string textnum = input;
        for (std::size_t i = 0; i < textnum.size(); ++i)
            if (textnum[i] == '-') textnum[i] = ' ';

        BigNum current;
        BigNum result;
        std::string curstring;
        bool onnumber = false;

        for (const std::string& w : split_words(textnum)) {
            std::string word = w;
            std::map<std::string, long long>::const_iterator ord = ordinal_words.find(word);
            if (ord != ordinal_words.end()) {
                // scale = 1, increment = ordinal value
                current.mul_add(1ULL, static_cast<unsigned long long>(ord->second));
                onnumber = true;
            } else {
                for (std::size_t k = 0; k < ordinal_endings.size(); ++k) {
                    const std::string& ending = ordinal_endings[k].first;
                    const std::string& replacement = ordinal_endings[k].second;
                    if (ends_with(word, ending))
                        word = word.substr(0, word.size() - ending.size()) + replacement;
                }

                std::map<std::string, std::pair<long long, long long> >::const_iterator it = numwords.find(word);
                if (it == numwords.end()) {
                    if (onnumber)
                        curstring += result.plus(current).str() + " ";
                    curstring += word + " ";
                    result = BigNum();
                    current = BigNum();
                    onnumber = false;
                } else {
                    long long scale = it->second.first;
                    long long increment = it->second.second;
                    current.mul_add(static_cast<unsigned long long>(scale),
