                const std::string& replacement = ordinal_endings[k].second;
                if (ends_with(word, ending))
                    word = word.substr(0, word.size() - ending.size()) + replacement;
            }
            if (numwords.find(word) == numwords.end())
                return false;
        }
        return true;
    }

private:
    std::map<std::string, std::pair<long long, long long> > numwords;
    std::vector<std::string> units;
    std::vector<std::string> tens;
    std::vector<std::string> scales;
    std::map<std::string, long long> ordinal_words;
