        }
        while (carry > 0ULL) {
            digits_.push_back(static_cast<int>(carry % 10ULL));
            carry /= 10ULL;
        }
    }

    BigNum plus(const BigNum& other) const {
        BigNum result;
        result.digits_ = digits_;
        if (result.digits_.size() < other.digits_.size())
            result.digits_.resize(other.digits_.size(), 0);
        int carry = 0;
        for (std::size_t i = 0; i < result.digits_.size(); ++i) {
            int sum = result.digits_[i] + carry;
            if (i < other.digits_.size())
                sum += other.digits_[i];
            result.digits_[i] = sum % 10;
            carry = sum / 10;
        }
        if (carry > 0)
            result.digits_.push_back(carry);
        return result;
    }

    std::string str() const {
        if (digits_.empty())
            return "0";
        std::string out;
        out.reserve(digits_.size());
        for (std::size_t i = digits_.size(); i-- > 0;)
            out.push_back(static_cast<char>('0' + digits_[i]));
        return out;
    }

private:
    // Little-endian decimal digits, no leading zeros; empty vector means 0.
    std::vector<int> digits_;
};

